/* The Unsent Museum — eight rewritten comparative research essays, five-part structure.
   Scope: the eight Comparative Research pages only. Other research rooms and assets are untouched.
   Source findings, curatorial interpretation and evidence limits are explicitly separated. */
(function(){
'use strict';
const atlas=window.MUSEUM_RESEARCH_ATLAS;
if(!atlas||typeof atlas.page!=='function')return;
const articles=[
{
title:['Why Is Saying No Difficult?','为什么拒绝如此困难？'],
subtitle:['A comparison of anticipated consequences, interpersonal judgments and the felt freedom to refuse.','比较拒绝后果的预期、人际判断，以及主观上的拒绝自由感。'],
ids:['R01','R02','R03'],
rows:[
['R01',['Refusers often predicted more negative reactions than requesters reported. The gap varied with the requester’s power and the likelihood of future contact.','拒绝者往往比请求者本人预期更负面的反应；这种预期差距会随请求者的权力和双方未来继续交往的可能性而变化。'],['Explains when anticipated social costs may be overestimated, while showing that power can change the pattern.','解释人们何时可能高估拒绝的社交代价，同时指出权力会改变这种偏差。']],
['R02',['Specific refusal wording increased reported freedom to refuse. The pooled change in observed compliance did not reach conventional statistical significance.','提供具体拒绝措辞提高了参与者报告的拒绝自由感；但实际服从行为的合并结果未达到传统统计显著性标准。'],['Separates feeling able to refuse from actually refusing.','区分“感觉能够拒绝”与“实际作出拒绝”。']],
['R03',['Across five studies, invitees tended to anticipate more negative reactions to declined leisure invitations than inviters reported.','五项研究显示，受邀者往往预期拒绝休闲邀请会带来更负面的反应，而邀请者实际报告的感受相对较轻。'],['Shows how the two sides of an ordinary invitation can misread each other.','揭示普通社交邀请中的双方可能如何误判彼此。']]
],
sections:[
{head:["Research Background & Literature","研究背景与文献介绍"],paras:[["The difficulty of refusing is not a single psychological problem. A person may anticipate a damaged relationship, feel unable to find acceptable words, or face a requester with real authority over them. R01 compares predicted consequences with requesters’ reports, R03 examines declined social invitations from both sides, and R02 tests whether supplying a refusal phrase changes a participant’s sense of freedom. These studies belong together because they separate the imagined consequences of saying no from the perceived ability to say it.","拒绝困难并不是一个单一的心理问题。有人担心关系受损，有人找不到合适的表达方式，也有人面对真正拥有决定权的请求者。R01比较拒绝者对后果的预测与请求者的实际报告；R03从邀请双方的角度研究社交邀请被拒绝后的反应；R02则检验提供具体拒绝措辞是否改变参与者的自由感。把它们放在一起，不是因为三项研究都证明了同一种沉默，而是因为它们分别揭示了“预想拒绝的后果”与“感到自己能够拒绝”之间的不同问题。"]]},
{head:["Comparative Analysis of Research Findings","研究结论的深度比较"],paras:[["R01’s seven main studies and four supplementary studies found a recurring gap between what refusers expected and what requesters reported. Refusers anticipated more negative emotional and relational consequences. This comparison is important because the evidence does not rest only on a refuser’s fear: it juxtaposes the forecasts of one party with the reactions reported by the other. Yet the study also shows that this gap varies with power and the prospect of future contact. The finding is therefore not a licence to dismiss every fear as groundless.","R01的七项主要研究和四项补充研究反复发现：拒绝者预想的负面情绪和关系后果，往往比请求者本人报告的反应更严重。其重要性在于，研究并非仅仅询问拒绝者有多害怕，而是把一方的预测与另一方的报告放在一起比较。不过，这种差距会随着请求者的权力和双方未来联系的可能性而变化。换言之，研究揭示了预期偏差，却没有赋予我们把所有拒绝恐惧都视为毫无根据的理由。"],["R03 independently finds a comparable mismatch across five studies of leisure invitations. Invitees expected declining to produce more disappointment, anger or relational damage than inviters reported. Together, R01 and R03 strengthen a limited conclusion: in at least some interpersonal situations, the anticipated interpersonal penalty for saying no is greater than the reaction reported by the person hearing it. R03 also narrows the interpretation. A leisure invitation is a social setting in which declining can be relatively ordinary; it is not interchangeable with rejecting an employer’s instruction, refusing an adult caregiver, or challenging someone who controls essential resources.","R03在五项关于休闲邀请的研究中发现了相似的判断落差：受邀者预想邀请者会更失望、更生气，或因此损害关系，但邀请者报告的负面反应相对较轻。R01与R03相互支持，使我们能够提出一个有限而有根据的判断：至少在某些人际情境中，说“不”的预期社交代价可能高于对方报告的真实反应。然而，R03同时收窄了这一判断的适用范围。拒绝一次休闲邀请，不能直接等同于拒绝雇主指令、成年照护者的要求，或拒绝掌握重要资源的人。"],["R02 does not repeat this prediction-versus-reaction comparison. In experiments involving a request to surrender an unlocked phone, participants who were given specific words for refusing reported more freedom to refuse than those only reminded of their right to decline. The pooled effect on subjective freedom was modest (d = 0.27). Crucially, the pooled difference in actual compliance did not reach the conventional threshold for statistical significance (OR = 1.54, p = .053). The result distinguishes a change in felt choice from evidence of a reliable change in behaviour.","R02并没有重复“预测与实际反应”的比较。在要求参与者交出已解锁手机的实验中，得到具体拒绝措辞的人，比仅被提醒有权拒绝的人报告了更高的拒绝自由感；合并的主观自由感效应量较小（d = 0.27）。关键在于，实际服从行为的合并差异未达到传统统计显著性标准（OR = 1.54，p = .053）。因此，研究证明的重点是人们对选择权的主观体验可能改变，而不是给一句话就能可靠地改变实际行为。"],["This contrast changes how the three studies should be read. R01 and R03 investigate a possible distortion in evaluating consequences; R02 investigates a resource that may make a formally available option feel usable. If the first two studies ask why someone expects refusal to be costly, the third asks why an available refusal can still feel inaccessible. They address adjacent stages of a decision rather than competing estimates of one effect. Nor does any one of them establish that changing a forecast will cause someone to refuse.","这种对照改变了我们阅读三项研究的方式。R01与R03考察人们是否高估拒绝后果；R02考察一种形式上存在的选择权，能否因为有了具体措辞而变得更容易使用。如果前两项研究追问“为什么一个人预期拒绝代价很高”，第三项则追问“为什么有权拒绝仍不等于感到能够拒绝”。它们研究的是决策过程的相邻环节，而不是对同一效应给出相互竞争的估计。任何一项研究也没有直接证明，改变后果预期就必然导致拒绝行为。"]]},
{head:["Explaining Agreements and Differences","共性、差异及其原因"],paras:[["The agreement between R01 and R03 is strongest at the level of interpersonal forecasting, not at the level of actual safety. Their designs make a mismatch between two perspectives visible, but a reported reaction is not a complete record of later consequences. An inviter who reports little disappointment today may behave differently over time; a participant may also have reasons to distrust the requester’s future response. The studies illuminate a common forecasting pattern without resolving every longer-term risk.","R01与R03最明确的共性存在于人际预测层面，而不是“拒绝实际上一定安全”。它们通过比较双方视角揭示判断落差，但对方当下报告的反应，并不等于对所有后续后果的完整记录。邀请者今天表示并不失望，不代表日后绝不改变行为；拒绝者也可能有理由担心对方未来的反应。因此，两项研究说明一种常见的预测模式，却不能消除所有长期风险。"],["R02 differs partly because its outcome is different. A self-reported sense of freedom measures what a participant feels possible, while compliance measures what the participant does. These need not move together. A person can recognise that refusal is permissible and still comply out of habit, uncertainty, politeness or perceived obligation. This is why the modest gain in felt freedom should not be described as an established behavioural intervention. The distinction between internal permission and outward action is itself a substantive finding of the comparison.","R02的差异首先来自结果指标不同。主观自由感测量参与者觉得什么是可能的，实际服从行为则测量他最后做了什么。两者并不必然同步。一个人可以清楚知道自己有权拒绝，却仍因习惯、犹豫、礼貌或义务感而答应。因此，不能把主观自由感的有限改善描述为已经证实有效的行为干预。把内心的“允许自己拒绝”和外在的“实际拒绝”区分开，本身就是这组比较得出的重要认识。"],["Power creates a further limit. The expected social cost of declining a friend’s invitation is not equivalent to the expected cost of refusing a superior who controls employment, grades, care or access to resources. R01’s sensitivity to power and future contact is a warning against treating all silence as a cognitive mistake. In unequal relationships, anticipated punishment may be realistic even when other participants in other settings overpredict rejection. The studies do not directly test a complete theory of coercion; the comparison nevertheless requires that possibility to remain open.","权力关系又构成了另一层限制。拒绝朋友邀请的预期代价，不能等同于拒绝掌握工作、成绩、照护或资源分配权者的预期代价。R01显示权力和未来联系会影响预测差距，这提醒我们不能把所有沉默都解释为认知错误。在不平等关系中，即使其他情境的参与者高估了负面反应，某些人的惩罚预期仍可能完全现实。这三项研究并未直接检验完整的胁迫理论，但综合解释必须为这种可能性保留位置。"],["The three findings are therefore compatible without being reducible to one mechanism. Forecasting another person’s reaction, finding a socially workable sentence, and assessing actual vulnerability to retaliation are different tasks. Their relative importance depends on the situation. A person may be able to speak but afraid of what follows; another may be relatively safe but unable to formulate a refusal; a third may experience both. A universal instruction to 'just say no' misses these distinctions.","因此，三项发现能够相互兼容，却不能被压缩成同一种机制。预测对方反应、找到社会情境中可用的措辞、判断自己是否真的会遭到报复，是三个不同任务；哪个更重要，取决于具体处境。有人知道怎么说，却害怕说完之后发生什么；有人并无明显危险，却不知道如何组织拒绝；也有人同时面对两种困难。笼统要求人们“勇敢说不”，恰恰忽略了这些区别。"]]},
{head:["The Museum’s Interpretation","本馆的综合结论"],paras:[["The Museum proposes a conditional account of unsaid refusal. Silence can arise when a person anticipates a cost that is larger than the other party’s likely reaction, when the person lacks an accessible way to state a boundary, or when the relationship contains a credible threat of punishment. These explanations can overlap, but they call for different responses. Better information may address exaggerated forecasts; usable language may ease expression; neither substitutes for protection against real retaliation.","本馆提出一种有条件的“未说出口的拒绝”解释：沉默可能发生在一个人高估对方反应时，也可能发生在他缺乏可使用的边界表达方式时，还可能发生在关系中存在可信的惩罚威胁时。这些原因可以重叠，却需要不同的回应。更准确的信息或许有助于修正过度悲观的预测，具体措辞或许能够减轻表达困难，但两者都不能替代对真实报复风险的保护。"],["The decisive question is therefore not simply whether a person possesses the right to refuse, but under what conditions that right becomes exercisable. An apparent 'yes' may conceal a wish to decline; an unspoken 'no' may reflect misjudgment, limited expressive resources or rational self-protection. Without evidence about the relationship and its consequences, observers should not assign one motive to every silence.","因此，关键问题不仅是一个人是否拥有拒绝权，而是这项权利在什么条件下真正能够被使用。表面上的“同意”可能掩盖拒绝的意愿；未说出口的“不”也可能来自判断偏差、表达资源不足，或理性的自我保护。如果不了解具体关系及其后果，旁观者就不应给所有沉默指定同一种动机。"],["This interpretation is a synthesis developed by the Museum, not a causal model jointly established by R01, R02 and R03. In particular, the evidence does not show that providing a script eliminates power-based pressure, that a corrected prediction necessarily changes behaviour, or that all refusals carry little risk. What the comparison does establish is the need to distinguish the feared consequence, the available means of expression and the actual social conditions before deciding why someone remained silent.","这一解释是本馆基于R01、R02、R03提出的综合判断，并非三项研究共同验证的因果模型。现有证据尤其不能证明：提供拒绝话术就能消除权力压力，纠正预测就必然改变行为，或者所有拒绝都没有太大风险。比较真正支持的是：在判断一个人为何保持沉默之前，应当分别考察他害怕的后果、可用的表达方式，以及实际所处的社会条件。"]]},
{head:["References & Evidence Notes","参考文献与证据说明"],paras:[["R01 — Lu, Fang & Qiu (2023), Rejecters Overestimate the Negative Consequences They Will Face From Refusal, Journal of Experimental Psychology: Applied. DOI: 10.1037/xap0000457. Forecasting results should not be equated with an absence of real retaliation.","R01 — Lu、Fang与Qiu（2023），《Rejecters Overestimate the Negative Consequences They Will Face From Refusal》，Journal of Experimental Psychology: Applied，DOI：10.1037/xap0000457。预期偏差不能被等同于真实报复风险不存在。"],["R02 — Schlund, Sommers et al. (2024), Giving People the Words to Say No Leads Them to Feel Freer to Say Yes, Scientific Reports. DOI: 10.1038/s41598-023-50532-3. The statistically supported subjective-freedom result must be distinguished from the uncertain pooled behavioural result.","R02 — Schlund、Sommers等（2024），《Giving People the Words to Say No Leads Them to Feel Freer to Say Yes》，Scientific Reports，DOI：10.1038/s41598-023-50532-3。主观自由感结果与尚不确定的合并行为结果必须分开表述。"],["R03 — Givi et al. (2024), Saying No: The Negative Ramifications From Invitation Declines Are Less Severe Than We Think, Journal of Personality and Social Psychology. DOI: 10.1037/pspi0000443. Its scope is declined invitations, not every type of unequal or coercive relationship.","R03 — Givi等（2024），《Saying No: The Negative Ramifications From Invitation Declines Are Less Severe Than We Think》，Journal of Personality and Social Psychology，DOI：10.1037/pspi0000443。研究范围是邀请被拒绝，而非所有不平等或强制性关系。"]]}
]

},
{
title:['The Bystander Effect in Context','不同情境中的旁观者效应'],
subtitle:['A comparison of emergency helping, meta-analytic moderators and psychological safety in teams.','比较紧急情境中的帮助行为、旁观者效应的调节因素，以及团队心理安全。'],
ids:['R08','R09','R10'],
rows:[
['R08',['In the classic intercom experiment, reported intervention was higher when participants believed they were the only potential helper than when they believed several others were present.','在经典对讲机实验中，认为自己是唯一潜在帮助者的参与者，报告事件的比例高于认为还有其他旁观者在场的人。'],['Shows how perceived responsibility can change in a controlled emergency.','呈现受控紧急情境中，责任感知如何影响行动。']],
['R09',['A meta-analysis of 105 independent effects found an overall bystander effect, but danger and the possibility of useful help moderated its strength.','涵盖105个独立效应量的元分析发现总体旁观者效应，但危险程度及旁观者能否提供有效帮助会调节效应强弱。'],['Tests whether the classic pattern holds across varied emergency conditions.','检验经典模式能否适用于不同紧急情境。']],
['R10',['Across 51 work teams, psychological safety was associated with learning behaviour; the study concerns speaking up and learning, not emergency rescue.','在51支工作团队中，心理安全与学习行为存在关联；研究关注表达与学习，而非紧急施救。'],['Adds a distinct organizational condition for speaking, rather than another bystander-effect test.','补充组织中安全表达的另一种条件，而不是再做一次旁观者效应检验。']]
],
sections:[
{head:["Research Background & Literature","研究背景与文献介绍"],paras:[["Why does a witness sometimes remain still when another person seems to need help? R08 studies the number of other people believed to be listening during an apparent emergency. R09 asks whether the resulting bystander pattern survives across many kinds of emergency. R10, included as a comparison rather than a replication, studies whether working teams feel safe enough to ask questions, admit errors and speak. The shared concern is response under social uncertainty, not an identical behaviour or population.","目睹他人需要帮助时，人为什么有时没有行动？R08研究紧急事件中，人们认为还有多少其他人在场；R09检验这一旁观者效应在不同危险情境下是否依然成立；R10作为对照研究，考察工作团队成员是否敢于提问、承认错误与表达意见。三项研究共同关心的是人在社会情境中如何回应问题，但它们研究的并不是同一种行为，也不是同一类人群。"]]},
{head:["Comparative Analysis of Research Findings","研究结论的深度比较"],paras:[["R08 makes a striking comparison. Participants listening to a simulated seizure over an intercom believed that either no other potential witness, one other witness, or four others could intervene. The percentages reporting the emergency before the apparent seizure ended were 85%, 62% and 31%, respectively. These figures concern action within a particular time window; they should not be confused with the proportion who eventually reported it. The key experimental result is that even without physically seeing a crowd, believing other helpers are available changes both the likelihood and timing of response.","R08的经典对讲机实验提供了鲜明的对照。参与者听见一场模拟的癫痫发作，并被安排相信除了自己之外，可能没有其他目击者、还有一名目击者，或者还有四名目击者。在模拟发作结束前报告事件的比例，依次为85%、62%与31%。必须注意，这些数字对应的是特定时间窗口中的行动比例，不能混同于最终是否曾经报告事件的比例。实验最重要的发现是：即使参与者看不见其他人，只要相信还有人能够伸出援手，回应的可能性与速度就可能改变。"],["The common explanation is diffusion of responsibility: when a person seems to be the sole possible helper, the obligation is difficult to pass on; when multiple others are believed to be available, each person may wait. But R08 does not observe every silent participant's private reasoning, and it does not prove that any one individual consciously decided that another person would help. It establishes a behavioural difference under experimentally manipulated group size, for which diffusion of responsibility is an interpretation.","常见的解释是责任分散：当一个人觉得自己是唯一能帮忙的人时，责任似乎无法推给别人；当其他人也被认为在场时，他可能更容易等待。然而，R08没有直接读取每一个沉默者的内心，也不能证明每个人都曾明确想着“别人会帮忙”。它直接确立的是：研究者改变参与者相信的在场人数后，行动出现了系统性差异；责任分散是对这种差异的一种重要解释。"],["R09 then tests the reach of that classic pattern rather than merely repeating it. Combining 105 independent effect sizes and more than 7,700 participants, its meta-analysis found an average negative bystander effect (Hedges' g about -0.33). The average confirms that the classic suppression pattern is not confined to one laboratory experiment. Yet the aggregate also hides meaningful variation. In some dangerous situations, particularly when another witness can provide physical support or when the danger is clearly identifiable, the negative effect is reduced and may cease to be negative.","R09进一步检验经典模式的适用范围，而不只是再做一次相同实验。它汇总105个独立效应量、超过7700名参与者，得到总体负向的旁观者效应（Hedges' g约为-0.33）。这说明经典实验所呈现的抑制倾向并非只存在于一个实验室情境。然而，平均效应同时掩盖了重要差别：在某些危险明确的事件中，尤其是其他目击者可以提供身体上的协助，或者危险信号很清楚时，负向效应可能减弱，甚至不再表现为负向。"],["That result limits an overly literal reading of R08. Other witnesses are not necessarily only competitors for responsibility; they can also become sources of information, courage, practical assistance or shared protection. A crowd might encourage inaction when a situation is ambiguous and nobody has an assigned role, but strengthen intervention when the costs of acting alone are high. R09 therefore qualifies the claim 'more witnesses means less help': what the witnesses are able to do, and what the situation demands, matter alongside their number.","这一发现限制了对R08的机械理解。其他目击者不一定只会分担、稀释个人责任，他们也可能提供信息、勇气、实际协助或共同保护。在情况模糊、无人明确承担任务时，人多可能促使彼此观望；但当独自行动风险很高时，旁人又可能增强介入的可能性。因此，R09修正了“人越多，越没人帮忙”的简单判断：除人数以外，其他人在场能够做什么、事件本身要求什么，同样关键。"],["R10 enters at a different point. In 51 work teams, Edmondson found that psychological safety was associated with learning behaviour. Members of a safer team could more readily raise questions, discuss mistakes or seek feedback without anticipating humiliating interpersonal consequences. Team efficacy did not replace this association when psychological safety was controlled. This is not emergency rescue evidence and it cannot confirm the magnitude of a bystander effect. Its contribution is to show that what makes speech possible in an established group may be perceived interpersonal safety rather than the number of observers.","R10研究的是另一类问题。Edmondson调查51支工作团队，发现心理安全与团队学习行为存在关联。成员如果相信提出问题、讨论失误、寻求反馈不会招致羞辱或其他严重人际惩罚，就更可能参与这类学习活动；在控制心理安全后，团队效能感不能替代这种关联。这不是紧急施救研究，也不能用于确认旁观者效应有多大。它提供的不同解释是：在一个持续运作的群体中，影响人们是否开口的可能是人际安全感，而不只是现场有多少人。"]]},
{head:["Explaining Agreements and Differences","共性、差异及其原因"],paras:[["R08 and R09 concern the same family of phenomena but occupy different levels of evidence. An experiment can isolate a perceived audience size; a meta-analysis can test how that relationship shifts across tasks and populations. The apparent tension between 'other people suppress action' and 'other people can facilitate action' is therefore not necessarily a contradiction. It arises because the meaning of another witness changes with danger, responsibility, and the usefulness of collective support.","R08与R09研究同一类现象，但处于不同的证据层次。受控实验可以隔离“我认为现场还有几个人”这个变量；元分析则能考察这种关系如何随着任务和人群改变。“其他人在场抑制行动”与“其他人在场可能促进行动”看似矛盾，实际未必互相否定。差异来自目击者的意义并不固定：在不同危险程度、责任分配方式和合作可能性下，另一个人既可能是等待的理由，也可能是行动的支持。"],["An additional distinction concerns ambiguity. In an uncertain event, one observer may look to others for signs that help is necessary, while each of those people may be doing the same. In clear danger, uncertainty about whether intervention is warranted may be reduced, even as concerns about personal safety remain. These are plausible mechanisms discussed in the bystander literature, not intentions individually verified for every participant in R08 or every study gathered by R09.","还必须区分情境是否模糊。在难以判断是否真的发生危险时，一个人可能观察别人的反应，以确认是否需要帮助；其他人却可能也在进行同样的观察。危险一旦明显，“是否需要行动”的不确定性可能降低，但“自己介入是否安全”的担忧依然存在。这些是旁观者研究中合理的解释机制，并非R08或R09已经逐一证实每位参与者内心想法的直接证据。"],["R10 differs even more fundamentally. Speaking up within a team often means maintaining relationships with the same colleagues after the incident, sometimes under a superior's evaluation. Emergency helping concerns a time-sensitive response to an event; team voice concerns the ongoing costs of exposing a question or mistake. There is a conceptual resemblance—people interpret other people's presence before responding—but transferring effect sizes or causal conclusions across the two settings would be unjustified.","R10的差异更根本。团队成员开口往往意味着事后仍要与同事继续共事，甚至接受上级评价；紧急施救则是对眼前事件作出及时反应。前者涉及持续的人际风险，后者涉及即时的帮助决策。两类情境在概念上确有相似之处：人们都会根据周围人的存在来判断行动是否可行。但我们不能把紧急情境的效应量直接套到工作团队，也不能把相关性证据说成确定的因果规律。"],["These differences also change what an intervention could mean. Assigning a named helper or making responsibility clear might address the uncertainty highlighted by R08. Providing safe channels for raising concerns might address the interpersonal risk described by R10. For a physically dangerous incident, collective support may be essential rather than harmful, as R09 suggests. The research does not test this combined programme; it cautions against treating every silence as the same failure.","这些区别也改变了所谓“干预”的含义。明确指定谁负责帮助，可能对应R08提示的责任不清；建立安全的表达渠道，可能对应R10讨论的人际风险；面对有身体危险的事件，R09又提示合作性支持可能是必要条件，而非妨碍。三项研究并未共同试验这样一整套方案，但足以提醒我们：不能把每一种不行动都当作同一种失败。"]]},
{head:["The Museum’s Interpretation","本馆的综合结论"],paras:[["The Museum interprets the silent witness conditionally. In some situations, silence is more likely when responsibility appears shareable and nobody is specifically called to act. In others, the decisive barrier may be uncertainty about what is happening, fear of personal danger, or the interpersonal cost of challenging a group. The mere number of people present cannot reveal which mechanism is active.","本馆对“沉默的见证者”提出一种条件性解释：在某些情境中，沉默可能因为责任似乎可以由别人承担、又没有人被明确指定行动而增加；另一些情境中，真正的障碍可能是无法判断事件性质、担忧自身安全，或者挑战群体所需承担的人际代价。仅仅数清现场有几个人，并不能知道是哪一种机制在起作用。"],["The implication is not to demand heroism from every witness. A safer response can require clear responsibility, an intelligible signal that help is needed, and practical support for the person who intervenes. Where the problem is repeated silence in an organization, protecting those who raise concerns may matter more than urging them to 'be brave'. Moral judgment should take account of the real options available to a person.","因此，本馆并不认为解决问题的方法是要求每个见证者都成为英雄。更可行的条件可能包括清晰的责任分配、能够辨认的求助信号，以及对介入者的实际支持。如果问题是组织中持续发生的集体沉默，那么保护提出异议的人，可能比不断呼吁他们“勇敢一些”更重要。评价一个人是否应该开口，必须考虑他实际上拥有什么选择。"],["This synthesis connects experiments on emergencies, a meta-analysis of helping, and observational work on teams; it is not a single tested model of all three behaviours. What it supports is a narrower and more useful principle: the decision to respond depends on whether one feels responsible, whether acting appears effective, and whether acting feels sufficiently safe. Silence cannot be diagnosed from group size alone.","这是本馆将紧急事件实验、帮助行为元分析与团队观察研究联系起来的解释，并不是三者共同验证的统一模型。比较所支持的是一项更有限、也更有用的判断：一个人是否回应问题，与他是否觉得自己有责任、行动是否可能有效，以及行动是否足够安全有关。群体人数本身，不足以解释沉默。"]]},
{head:["References & Evidence Notes","参考文献与证据说明"],paras:[["R08 — Darley & Latané (1968), Bystander Intervention in Emergencies: Diffusion of Responsibility. The 85%, 62% and 31% figures concern responses before the simulated seizure ended, not eventual response rates. R09 — Fischer et al. (2011), The Bystander-Effect: A Meta-Analytic Review. Meta-analytic results depend on contexts and moderators. R10 — Edmondson (1999), Psychological Safety and Learning Behavior in Work Teams. The team finding is correlational, not a second bystander experiment.","R08 — Darley与Latané（1968），《Bystander Intervention in Emergencies》；85%、62%、31%指模拟发作结束前的回应比例，不是所有参与者最终回应的比例。R09 — Fischer等（2011），《The Bystander-Effect: A Meta-Analytic Review》；平均效应受研究情境与调节因素影响。R10 — Edmondson（1999），《Psychological Safety and Learning Behavior in Work Teams》；团队发现属于关联性证据，不是另一项旁观者效应实验。"]]}
]
},
{
title:['When Power Shapes Voice','权力如何影响表达？'],
subtitle:['How workplace safety, organizational silence and hidden transcripts illuminate the conditions of speaking.','从职场心理安全、组织沉默与隐藏话语，理解表达受到哪些条件影响。'],
ids:['R10','R11','R12','R13','R30'],
rows:[
['R10',['Psychological safety was associated with learning behaviour in 51 work teams.','在51支工作团队中，心理安全与学习行为存在关联。'],['Shows how interpersonal risk affects speaking and learning within teams.','呈现团队内部的人际风险如何影响表达与学习。']],
['R11',['Organizational structures and managerial assumptions may normalize silence and block upward feedback.','组织结构与管理者的预设可能使沉默常态化，并阻断向上反馈。'],['Offers a theoretical model of how silence can become institutional.','提供沉默如何制度化的理论模型。']],
['R12',['The review distinguishes employee voice from silence and maps individual, leadership and organizational influences.','综述区分员工表达与沉默，并梳理个人、领导及组织因素。'],['Clarifies the field and its evidence gaps.','梳理研究领域并指出证据空缺。']],
['R13',['Leadership openness was associated with employee voice; psychological safety helps explain the relationship.','领导开放性与员工表达存在关联，心理安全有助于解释这种关系。'],['Connects leader behaviour with opportunities to speak.','连接领导行为与表达机会。']],
['R30',['Public and hidden transcripts distinguish what is said under power from criticism expressed away from authority.','公开话语与隐藏话语区分了权力面前的表达，以及离开权威视线后的批评。'],['Adds a historical and political account of speech under domination.','补充支配关系下表达的历史与政治解释。']]
],
sections:[
{head:["Research Background & Literature","研究背景与文献介绍"],paras:[["Silence in a workplace or under political authority cannot be explained only as a shy individual's failure to speak. R10 studies psychological safety in teams; R13 examines leaders' openness and employee suggestions; R11 theorizes how an organization produces collective silence; R12 reviews the wider literature on employee voice; and R30 contrasts public speech with criticism voiced outside the view of power. Their evidence differs, but together they ask who controls the conditions under which a statement becomes safe, meaningful or consequential.","工作场所或权力关系中的沉默，不能只用个人胆怯来解释。R10研究团队心理安全，R13考察领导开放性与员工建议，R11提出组织如何形成集体沉默的理论，R12综述员工表达研究，R30则区分权威面前的公开言说与权力视线之外的批评。五项资料的证据类型并不相同，但都促使我们追问：究竟是谁决定一句话在什么条件下能够被安全地说出、被认真对待，并产生实际后果？"]]},
{head:["Comparative Analysis of Research Findings","研究结论的深度比较"],paras:[["R10's evidence begins inside 51 work teams. Edmondson found that team psychological safety was associated with learning behaviours such as discussing mistakes, asking for help and seeking feedback. Importantly, the relationship did not disappear simply because a team believed itself competent: after psychological safety was taken into account, team efficacy did not explain learning in the same way. The implication is not that confidence is useless, but that confidence in being capable is different from confidence that one may take an interpersonal risk without humiliation.","R10首先从51支工作团队提供证据。Edmondson发现，团队心理安全与讨论失误、寻求帮助、征求反馈等学习行为存在关联。尤其重要的是，团队认为自己有能力，并不能简单取代成员认为表达是安全的这一条件：在考虑心理安全后，团队效能感没有以相同方式解释学习行为。这不意味着能力自信毫无价值，而是说明“相信我们做得到”和“相信我敢把错误说出来而不受羞辱”不是同一件事。"],["R13 extends this argument from general team climate to leaders' behaviour. Detert and Burris examined improvement-oriented employee voice and distinguished different forms of change-oriented leadership. Managerial openness was associated with employees' willingness to offer constructive suggestions, with psychological safety helping account for the relationship. That is a more specific result than the claim that a charismatic or inspiring leader automatically produces openness: employees appear to attend to whether their immediate superior seems receptive when the suggestion challenges current practice.","R13把讨论从一般团队氛围推进到领导者行为。Detert与Burris考察员工旨在改善组织的建议表达，并区分不同类型的变革型领导行为。研究发现，管理者的开放性与员工提出建设性意见存在关联，心理安全有助于解释这种关系。这个结果比“有魅力、会激励人的领导就能让员工开口”更具体：员工会留意直接上级是否真正愿意接受可能挑战现有做法的意见。"],["R10 and R13 therefore converge on interpersonal risk but do not ask identical questions. R10 links a team's shared climate to learning; R13 links perceived leader behaviour to a particular kind of upward voice. Neither should be reduced to the trivial statement that 'nice leaders make people talk'. Safety is about the expected response to error, disagreement or uncertainty, especially when what is said is inconvenient to someone with more authority.","因此，R10与R13都把人际风险放在重要位置，却并非研究同一个结果。R10连接团队共同氛围与学习，R13连接员工对领导行为的感受与向上提出改善建议。两者都不能被简化成“领导和善，员工就会说话”。所谓安全，指的是当一个人承认错误、表示不同意或提出疑问，尤其当这些话令更有权力者不舒服时，他预期自己会受到怎样的对待。"],["R11 changes the scale. Morrison and Milliken propose that collective silence can become a feature of an organization itself. Management assumptions about employees, centralized decision-making and the absence of credible upward channels may discourage dissent. When employees observe that criticism is unwelcome, each instance of withholding feedback helps preserve leaders' mistaken impression that there is little disagreement. R11 is a theoretical argument about a self-reinforcing system, not a new experiment proving that every organization follows one exact sequence.","R11把分析尺度从个体和团队扩大到组织本身。Morrison与Milliken提出，集体沉默可能成为组织结构的一部分。管理者对员工的固有假设、集中决策与缺少可信的向上反馈渠道，都可能抑制异议。员工看到批评不受欢迎，就更少表达；管理者则可能把听不到反对声误认为大家没有不同意见，进一步维持原有安排。R11提出的是一种可能自我强化的组织机制，而不是通过一项新实验证明所有组织必然沿同一过程发展。"],["R12 places this theoretical account alongside a broad review of employee voice and silence research. It treats speaking up and withholding input as consequential behaviours influenced by individual assessments, managerial responses and organizational context. The review also cautions against understanding silence simply as the opposite of voice: not offering an improvement idea may reflect fear, resignation, perceived ineffectiveness or other motives. As a synthesis of a field, R12 organizes existing evidence; it does not supply one uniform effect size for every motive.","R12把上述理论放入更广泛的员工表达与沉默研究中讨论。综述表明，是否提供建议受到个人判断、领导回应与组织环境等多种条件影响；同时，沉默不能简单理解为表达的反面。一个人不提出改善意见，可能因为恐惧、放弃希望、认为表达无效，或出于其他动机。作为领域综述，R12的价值在于整理不同发现及其边界，而不是提供一个能解释所有沉默原因的统一效应量。"],["R30 introduces a more disruptive possibility. Scott's account of public and hidden transcripts suggests that subordinated people may voice compliance before authority while circulating criticism, humour or resistance outside its immediate gaze. This is not merely a lack of confidence. Public agreement can be a strategic performance under domination, while criticism persists in spaces from which the powerful are absent. Scott's historical and political argument cannot be treated as another employee survey, but it challenges the assumption that an apparently quiet group has nothing to say.","R30提出了一个更有冲击力的可能性。Scott区分公开话语与隐藏话语：处于从属地位的人可能在权威面前表现为顺从，却在权力视线之外通过议论、讽刺或其他方式表达批评与抵抗。这不只是缺乏自信的问题。公开的赞同可能是支配关系中的策略性表演，而批评并未消失，只是移到了权威看不到的场所。Scott的历史与政治理论不能当作另一份员工问卷，但它有力地挑战了“一个群体没有公开反对，就说明它无话可说”的假设。"]]},
{head:["Explaining Agreements and Differences","共性、差异及其原因"],paras:[["The five works agree on one proposition: expressions of disagreement are shaped by the social consequences expected after speaking. But the consequences differ in kind. R10 and R13 focus on interpersonal risks inside organizations; R11 considers how structures and management assumptions reproduce silence; R30 examines domination, where public statements can become performances required for survival. These are related levels of power, not synonyms for 'feeling nervous'.","五项资料的共同判断是：人们是否表达异议，受到说出之后可能发生什么的影响。但这些后果并不属于同一种性质。R10与R13关注组织内部的人际风险，R11解释制度安排和管理预设如何不断再生产沉默，R30则研究更深层的支配关系，在那里公开表态可能成为求生存所必须进行的表演。这些都是与权力有关的层次，却不能被统称为“有点紧张”。"],["The works also differ in what counts as 'speaking'. In R13, voice is usually an improvement-oriented suggestion offered to an organization. Scott's hidden transcript may involve satire or dissent that has no intention of improving the ruler's institution. One may hope a superior will act on a suggestion; another may deliberately keep criticism out of a superior's hearing. Treating both as unsuccessful workplace feedback would mistake the speaker's purpose.","这些文献对“表达”的定义也不同。在R13中，表达通常意味着向组织提出改善性建议；Scott所讨论的隐藏话语则可能包含讽刺与异议，根本不打算帮助统治者改善制度。有的人希望上级采纳建议，有的人恰恰要确保批评不会传到上级耳中。如果把两者都视为“反馈没有成功”，就误解了说话者自身的目的。"],["Differences in method help explain the contrast. R10 and R13 offer empirical associations measured among teams or employees, while R11 and R30 primarily develop theoretical interpretations from distinct traditions. R12 reviews a varied literature. The theoretical works can identify mechanisms that a survey may fail to ask about, but they do not establish their prevalence in a given workplace. Conversely, a workplace correlation cannot by itself prove the wider historical argument about domination.","研究方法的差异有助于解释这些结论为何不同。R10与R13在团队或员工中测量经验性关联；R11和R30主要从不同学术传统提出理论解释；R12则综合多类研究。理论作品可能指出问卷根本没有提问的机制，却不能据此计算某个工作场所中这种机制出现的比例；反过来，一项职场相关性也不足以证明整个历史上的支配关系都遵循相同规律。"],["One genuine tension remains. An institution may encourage more suggestions while still deciding which kinds of criticism are acceptable. A supervisor could welcome technical improvements but reject questioning the distribution of authority. Psychological safety for one form of voice is therefore not proof of full freedom of expression. None of the cited studies directly tests this entire boundary, yet Scott's distinction warns us to ask what remains unsayable even in a team celebrated as 'open'.","这里还存在一个真正值得保留的张力：一个组织可能鼓励更多建议，却仍由自己决定哪一种批评可以被提出。上级可能欢迎技术改进，却拒绝任何关于权力分配的质疑。因此，员工敢于提出某一类意见，并不证明他们拥有充分的表达自由。所列研究没有共同直接检验这一边界，但Scott的区分提醒我们：即使一支团队被称为“开放”，仍应追问究竟有哪些话不能说。"]]},
{head:["The Museum’s Interpretation","本馆的综合结论"],paras:[["The Museum sees organizational silence not as a single absence of sound but as a distribution of permission. Some people may speak about errors but not authority, suggest improvements but not challenge a policy, or criticize freely in private while publicly agreeing. The meaningful question is not merely how much is said, but which subjects, speakers and audiences are permitted to meet without retaliation.","本馆认为，组织中的沉默并不只意味着声音缺席，而是体现了表达许可如何被分配。有的人能够讨论工作失误，却不能质疑权威；能够建议改进，却不能挑战政策；能够在私下自由批评，却只能在公开场合附和。因此，值得追问的不是“这里有多少人说话”，而是“哪些人能够对哪些听众谈论哪些问题，而不会因此受到惩罚”。"],["This account implies that the quality of a speaking environment cannot be judged by leaders' invitations to 'share openly' alone. A credible test concerns what happens after a difficult suggestion is made: whether the speaker is heard, whether dissent is documented fairly, whether retaliation is prevented, and whether the permitted topics include questions about power itself. These criteria follow as a curatorial implication; they are not a tested intervention package from the five sources.","由此，不能只因为领导说过“欢迎坦诚交流”，就认定表达环境已经改善。更可信的检验发生在真正难听的意见被提出之后：发言者是否得到认真回应，异议是否被公平记录，报复是否受到约束，以及能否讨论权力本身。这些是本馆从比较中提出的策展判断，并非五项文献共同试验过的一套干预方案。"],["The evidence supports a conditional conclusion: when the interpersonal cost of speaking is high or channels are not credible, withholding information may be a rational response; when criticism survives offstage, official quiet should not be mistaken for consent. R10 and R13 describe associations that may make constructive voice more likely, while R11, R12 and R30 explain why the limits of voice can be embedded in institutional arrangements. Those levels must remain distinct.","证据支持的因此是一项有条件的结论：当说话的人际代价很高，或反馈渠道缺乏可信度时，保留信息可能是理性的应对；当批评转移到权力视线之外时，正式场合的安静更不能被误认为同意。R10与R13说明哪些条件与建设性表达有关，R11、R12与R30则帮助解释表达的边界如何嵌入制度安排。这几个层次应该联系起来理解，却不能相互替代。"]]},
{head:["References & Evidence Notes","参考文献与证据说明"],paras:[["R10 — Edmondson (1999), Psychological Safety and Learning Behavior in Work Teams; R11 — Morrison & Milliken (2000), Organizational Silence; R12 — Morrison (2014), Employee Voice and Silence; R13 — Detert & Burris (2007), Leadership Behavior and Employee Voice; R30 — Scott (1990), Domination and the Arts of Resistance. R10/R13 are empirical organizational studies; R11/R30 develop theory; R12 reviews literature. Their evidentiary weights and contexts should not be conflated.","R10 — Edmondson（1999），《Psychological Safety and Learning Behavior in Work Teams》；R11 — Morrison与Milliken（2000），《Organizational Silence》；R12 — Morrison（2014），《Employee Voice and Silence》；R13 — Detert与Burris（2007），《Leadership Behavior and Employee Voice》；R30 — Scott（1990），《Domination and the Arts of Resistance》。R10与R13主要提供组织实证研究，R11与R30侧重理论，R12是文献综述；不能把不同资料的证明力和适用情境混为一谈。"]]}
]
},
{
title:['Gratitude, Disclosure and Apology','感谢、披露与道歉'],
subtitle:['Why different forms of emotional expression cannot be treated as one universal relationship skill.','为什么不同形式的情感表达不能被视为一种普遍适用的关系技巧。'],
ids:['R15','R16','R19','R21'],
rows:[
['R15',['Perceived responsiveness after expressed gratitude was associated with subsequent relationship-quality improvement over six months.','表达感谢后，接收者感受到的回应性与随后六个月的关系质量改善存在关联。'],['Highlights the recipient’s experience, not merely the act of saying thank you.','强调接收者的感受，而不只是表达感谢这一行为。']],
['R16',['Daily gratitude predicted next-day relationship connection and satisfaction; indebtedness did not show the same distinct pattern.','日常感恩能够预测次日关系连接感和满意度；负债感没有呈现同样独特的模式。'],['Distinguishes gratitude from feeling obliged.','区分感恩与觉得自己欠人情。']],
['R19',['Meta-analysis found bidirectional links between disclosure and liking, with substantial variation by research design and context.','元分析发现自我披露与好感之间存在双向联系，但结果会随研究设计和情境而显著变化。'],['Shows that disclosure is neither uniformly beneficial nor a one-way cause.','说明披露并非总有益，也不是单向因果过程。']],
['R21',['More complete apologies tended to receive better effectiveness ratings; accepting responsibility and offering repair were important components.','包含更多关键要素的道歉通常获得更高有效性评价；承担责任与提出补救是重要组成部分。'],['Separates apology structure from actual long-term reconciliation.','区分道歉结构与现实中的长期和解。']]
],
sections:[
{head:["Research Background & Literature","研究背景与文献介绍"],paras:[["Gratitude, personal disclosure and apology all involve saying something emotionally significant, but they are not interchangeable acts. R15 and R16 examine gratitude in close relationships; R19 reviews how disclosure and liking are linked; R21 tests which elements make an apology seem effective. Comparing them matters precisely because 'expressing feelings' can signal appreciation, invite intimacy, or acknowledge harm. Each act changes a relationship through a different social process.","感谢、自我披露和道歉都需要说出具有情感分量的话，但它们不是可以互换的行为。R15与R16关注亲密关系中的感恩，R19综述自我披露与好感的联系，R21考察哪些道歉要素更容易被认为有效。比较这些研究的意义，恰恰在于“表达情感”可能意味着确认对方的付出、邀请彼此靠近，或承认自己造成的伤害。每一种表达所涉及的关系机制并不相同。"]]},
{head:["Comparative Analysis of Research Findings","研究结论的深度比较"],paras:[["R15 highlights the interpersonal reception of thanks, not merely the fact that kind words were uttered. Research on expressed gratitude indicates that the recipient's sense of the expresser's responsiveness is central to understanding subsequent relationship quality. Evidence includes a longer follow-up over roughly six months, but the available verified material does not justify assigning a single universal effect size to every couple. The finding suggests that thanks may matter because of what the exchange communicates about being seen and valued, not because polite words operate as an automatic reward.","R15强调的不是“说了感谢”这个动作本身，而是感谢如何被接收和理解。关于表达性感恩的研究指出，伴侣如何感受到对方的回应性，是理解后续关系质量的重要线索；相关研究还包含约六个月的后续追踪。不过，目前可核查的资料不足以让我们为所有伴侣断言一个统一的效应量。这项发现提示，感谢之所以有意义，可能是因为双方在互动中感到自己的付出被看见、自己的需要受到重视，而不是礼貌用语自动发挥了奖励作用。"],["R16 reaches a related finding through everyday observation rather than one staged exchange. In a fourteen-day diary study involving 67 cohabiting heterosexual couples, gratitude connected to daily interactions predicted greater connection and relationship satisfaction on the following day. The same pattern was not found in the same way for indebtedness, the feeling that one owes the benefactor something. This distinction matters: gratitude can recognise care without reducing the relationship to an account to be repaid. R15 and R16 therefore converge on relational meaning while measuring different time scales and experiences.","R16不是只观察一次精心安排的表达，而是走进日常生活。在涉及67对同居异性伴侣、持续14天的日记研究中，一天互动中体验到的感恩，可以预测次日更高的关系连接感和满意度；“觉得欠对方人情”的负债感则没有呈现同样的独特模式。这个区别很重要：感恩可以是对照顾的认可，却不必把关系变成必须偿还的账目。R15与R16都强调感恩的关系意义，但它们测量的时间范围和心理体验不同。"],["R19 adds a new question: is intimacy created by telling another person more about oneself? Collins and Miller's meta-analysis did not identify a single one-way rule. It examined three distinct links: disclosure influencing liking, liking influencing disclosure, and people disclosing more to those they already like. Across 94 effect sizes in the first grouping, the average association was modest (d = 0.281); another grouping of 31 effect sizes yielded a substantially larger average (d = 0.717). The difference between these results warns against quoting 'disclosure builds liking' as a context-free formula.","R19提出另一个问题：向别人讲述更多自己，是否就能创造亲密？Collins与Miller的元分析并没有找到一个单向、恒定的规律，而是区分三种联系：披露如何影响好感、好感如何影响披露，以及人们是否更愿意向原本喜欢的人披露。在第一类比较中，94个效应量的平均结果较为温和（d = 0.281）；另一类31个效应量的平均结果明显更大（d = 0.717）。这些结果之间的差距提醒我们，不能把“多讲心事就会被喜欢”当作不受情境限制的公式。"],["The meta-analysis further reports substantial variation with research design and social context. A disclosure welcomed between trusted partners may feel intrusive between strangers, and a confident inference about a long-term friendship cannot be drawn from a brief experimental impression. R19 therefore complements the gratitude studies by identifying the importance of a responsive audience, but differs in another respect: it also makes visible how disclosure and prior liking may reinforce each other, complicating simple claims about what causes what.","元分析还发现结果会随研究设计和社会情境明显变化。在信任关系中受到欢迎的坦诚，对陌生人可能显得冒犯；一次实验中的好感判断，也不能直接当作长期友谊的结果。R19因此从另一侧补充了感恩研究：接受表达的一方如何回应非常重要。但它又提出不同的问题——人们可能因为已经喜欢某个人才愿意披露，而披露之后又进一步增进好感。双向联系使“究竟是谁先导致谁”的简单说法变得不可靠。"],["R21 shifts from appreciation and intimacy to repairing a violation. In two scenario-based studies involving 755 respondents, Lewicki and colleagues compared apologies containing different combinations of six components. Acknowledging responsibility and offering repair were especially important to perceived effectiveness; an explanation alone could not simply substitute for them. More components generally received more favourable ratings, but the research measured judgements about apologies in described situations, not actual reconciliation after personal harm. The distinction between competence-based and integrity-based violations also matters to how an apology is received.","R21则从感谢与亲密转向伤害之后的修复。在两项共755人参加的情境研究中，Lewicki及同事比较了包含六种不同道歉要素的表达。承认责任、提出补救等要素，对道歉被认为有效尤其重要；仅仅解释原因，不能简单取代承担责任。总体而言，包含更多重要要素的道歉通常得到较高评价，但研究测量的是参与者对情境中道歉的有效性判断，而不是亲身遭受伤害后是否真正和解。此外，能力失误与诚信失误会影响人们如何理解道歉。"],["Putting the four sources beside one another reveals three different audiences. Gratitude addresses someone who has done good; disclosure asks another person to receive vulnerability; apology addresses someone who has been wronged. Their common dependence on reception does not erase the different obligations involved. A harmed person is not required to forgive merely because an apology contains all six elements; a listener does not owe intimacy because someone disclosed a secret; and thanks do not oblige anyone to continue a relationship.","把四项研究并排阅读，我们会看见三种不同的接受者。感谢面对曾给予帮助的人；自我披露请求别人接纳自己的脆弱；道歉则面对遭受伤害的人。它们都依赖接受者如何理解表达，却因此承担着不同的责任。受害者不会因为道歉包含六项要素就有义务原谅；听者不会因为有人说了秘密就有义务建立亲密关系；接受感谢也不意味着必须继续维持某段关系。"]]},
{head:["Explaining Agreements and Differences","共性、差异及其原因"],paras:[["The strongest agreement is about relational interpretation. Words do not produce intimacy or repair simply by being spoken. Their meaning is negotiated against the history of a relationship, the receiver's expectations and the conduct that surrounds them. R15–R16 point to responsive gratitude; R19 shows that prior liking and context alter disclosure's effects; R21 shows that an apology's content is judged against a violation. These are parallel forms of interpretation, not an experimentally confirmed single mechanism.","四项研究最明确的共性是：表达的效果取决于关系中的解释过程。话语不会仅因被说出来，就自动产生亲密或修复。它们的意义需要放在双方的过往、接受者的预期以及言语之外的行为中理解。R15与R16强调感恩中的关系回应，R19显示既有好感与情境改变披露的效果，R21则表明道歉内容需要放在过错背景中评价。这些是彼此平行的解释过程，而不是经过四篇研究共同验证的单一机制。"],["The differences also follow from what each expression asks of the other person. Thanks may invite mutual recognition; disclosure may request attention or trust; apology may acknowledge responsibility and propose restitution. A disclosure can be sincere but mistimed. A thank-you can be warm but experienced as formulaic. An apology can sound emotionally convincing while leaving the original harm unaddressed. Consequently, emotional intensity and interpersonal benefit should not be treated as the same measure.","差异还来自每一种表达向对方提出的要求不同。感谢可能邀请相互认可，披露可能请求关注与信任，道歉则需要承认责任并考虑补救。一段披露即使真诚，也可能不合时宜；一句感谢即使温暖，也可能被理解为例行客套；一番道歉即使情绪动人，也可能对原本的伤害毫无补救。因此，表达得有多强烈，与关系是否真正得到改善，不应被当作同一个指标。"],["Methodology sets an additional boundary. R16 follows daily fluctuations in real couples; R19 pools heterogeneous disclosure studies; R21 asks participants to evaluate scenarios. They estimate different kinds of evidence, with different horizons and limitations. Comparing a next-day relationship score with a one-time hypothetical apology rating cannot yield a ranking in which gratitude is 'better' than apology. Nor should associations in diaries be rewritten as proof that every grateful expression causes lasting improvement.","研究方法又划出一条边界。R16观察真实伴侣生活中的每日变化，R19汇总差异很大的披露研究，R21让参与者评价假设情境。它们提供的证据在时间尺度和适用范围上都不同。不能把次日关系满意度与一次道歉情境的主观评分直接相减，然后宣布感谢“优于”道歉；也不能把日记中的统计关联改写为“每句感谢都会导致长期改善”的因果结论。"],["One tension remains unresolved: expression may support a relationship while also creating pressure to respond. The reviewed research does not jointly measure emotional obligation or coercion across all four practices. A person's silence after receiving gratitude, disclosure or apology is therefore not necessarily a rejection of care; it may indicate uncertainty, a boundary, or the need for time. The findings give reasons to attend to reception, not permission to prescribe compulsory openness.","还有一种尚未被这四项资料共同解决的张力：表达可能有助于关系，也可能让对方感到必须回应。现有研究并没有在四类表达中统一测量情感义务和强迫。因此，一个人在收到感谢、听见心事或面对道歉后保持沉默，不必然说明他拒绝善意，也可能意味着不确定、需要边界，或需要更多时间。这些研究支持我们重视接受过程，却不能成为要求所有人必须坦诚回应的依据。"]]},
{head:["The Museum’s Interpretation","本馆的综合结论"],paras:[["The Museum does not regard emotional expression as a universally good act. Its ethical and relational value depends on its purpose, its fit with the situation and the receiver's freedom to respond. Gratitude is meaningful when care is recognised rather than counted as debt. Disclosure may build connection when it is welcomed and appropriately situated. Apology matters most when it acknowledges harm and makes repair possible rather than merely seeking absolution.","本馆不把“表达情绪”视为一种无条件的善。它的关系价值与伦理意义，取决于表达的目的、是否适合当下情境，以及接受者能否自由回应。感谢的价值在于让关怀被看见，而不是制造欠债；披露可能在受到欢迎、情境恰当时促进连接；道歉则应当承认伤害、创造补救的可能，而不只是请求对方免除自己的内疚。"],["This perspective changes how the museum reads unsent words. An unspoken thank-you can mark a missed recognition, but it need not mean a relationship has failed. An undisclosed truth may preserve a legitimate boundary. An unspoken apology may leave harm without acknowledgement, yet speaking an apology without responsibility may also fail to repair it. The museum therefore evaluates not simply whether the words were delivered, but what kind of relationship the delivery would create.","这一理解改变了本馆阅读“未寄之言”的方式。没说出口的感谢可能是一次错过的认可，却不代表整段关系已经失败；没有披露的秘密可能维护正当边界；没有道歉可能使伤害缺少承认，但没有责任的道歉即使说出口，也未必完成修复。因此，本馆不能只问“话有没有送达”，还应追问“它会建立怎样的关系”。"],["This is a curatorial synthesis, not a cross-study causal experiment. The sources do not prove that any specific phrase creates intimacy, forgiveness or long-term stability for everyone. They support a more careful judgment: emotionally important speech is a relational act whose meaning depends on what is acknowledged, who receives it, and what actions follow. A person can be heard without the hearer being obligated to agree, reciprocate or forgive.","这是本馆的策展综合，并非一项贯穿四种表达的因果实验。上述资料没有证明哪句特定的话一定能为所有人创造亲密、宽恕或长期稳定。它们支持的是更审慎的判断：重要的情感表达是一种关系行为，其意义取决于承认了什么、由谁接收，以及之后如何行动。一个人的话可以被认真听见，但听见的人没有义务同意、回报或原谅。"]]},
{head:["References & Evidence Notes","参考文献与证据说明"],paras:[["R15 — Algoe, Fredrickson & Gable (2013), The Social Functions of the Emotion of Gratitude via Expression; R16 — Algoe, Gable & Maisel (2010), It's the Little Things; R19 — Collins & Miller (1994), Self-Disclosure and Liking; R21 — Lewicki, Polin & Lount (2016), An Exploration of the Structure of Effective Apologies. Separate daily-diary associations, meta-analytic comparisons and scenario ratings; none proves universal reconciliation.","R15 — Algoe、Fredrickson与Gable（2013），《The Social Functions of the Emotion of Gratitude via Expression》；R16 — Algoe、Gable与Maisel（2010），《It's the Little Things》；R19 — Collins与Miller（1994），《Self-Disclosure and Liking》；R21 — Lewicki、Polin与Lount（2016），《An Exploration of the Structure of Effective Apologies》。日记关联、元分析比较和情境评分须区别理解，均不能被当作普遍和解的证明。"]]}
]
},
{
title:['Family Communication and Topic Avoidance','家庭沟通与话题回避'],
subtitle:['How family communication patterns, avoided topics and social sharing offer different explanations of what remains unsaid.','比较家庭沟通模式、话题回避与情绪分享，理解家庭中未说出口的话。'],
ids:['R17','R18','R20'],
rows:[
['R17',['Conversation and conformity orientations offer a framework for understanding different family communication climates.','谈话取向与一致性取向构成理解不同家庭沟通氛围的框架。'],['Explains family-level patterns, not the motive behind one person’s silence.','解释家庭整体互动模式，而非某个人沉默的具体动机。']],
['R18',['Topic avoidance varies with the relationship and the subject being discussed; the evidence available in the dossier does not support universal claims about all families.','话题回避会随关系和谈论主题而变化；目前档案可核实的证据不足以支持对所有家庭作出普遍判断。'],['Brings the analysis to concrete topics people avoid with family members.','把分析落到家庭成员实际回避的具体话题。']],
['R20',['The review discusses social sharing of emotion and possible functions such as connection, validation and meaning-making.','综述讨论情绪的社会分享，以及联结、确认和意义建构等可能功能。'],['Explains why people may share feelings, without proving that everyone must disclose.','解释人们为何可能分享感受，但不证明每个人都必须披露。']]
],
sections:[
{head:["Research Background & Literature","研究背景与文献介绍"],paras:[["Families are often described as places where people should be able to speak freely. But which families encourage discussion, which topics remain difficult, and what does sharing an emotion actually do? R17 provides a framework for family communication climates; R18 documents patterns of topic avoidance with different relatives; R20 reviews the social sharing of emotion more broadly. Reading them together requires distinguishing a family's general communication norms from a person's decision to conceal a specific experience.","家庭常被想象为一个能够坦诚交流的地方。但什么样的家庭鼓励讨论？哪些话题仍然难以启齿？向别人讲述情绪究竟产生了什么作用？R17提出家庭沟通模式的理论框架，R18调查人们如何在不同家人面前回避不同话题，R20则从更广泛的人际交往研究综述情绪的社会分享。把三者放在一起，必须区分家庭整体的沟通规范，与某个人是否愿意讲述一件具体经历。"]]},
{head:["Comparative Analysis of Research Findings","研究结论的深度比较"],paras:[["R17 distinguishes two dimensions that are easily confused. Conversation orientation concerns how strongly a family encourages members to discuss many topics and participate in decisions. Conformity orientation concerns how strongly members are expected to share attitudes, values and a common family position. These dimensions can coexist: a household may talk frequently while expecting agreement, or offer relatively little discussion without imposing an equally strong demand for conformity. R17 thus challenges the simplistic assumption that a talkative household must also be a space for dissent.","R17区分了两个经常被混淆的维度：谈话取向关注家庭有多大程度鼓励成员讨论广泛话题、参与决定；一致性取向则关注家庭在多大程度上要求成员认同共同的态度、价值与立场。这两者可以同时存在：一个家庭可能经常说话，却仍要求最终意见一致；另一个家庭谈话不多，却未必对观点施加同样强的统一要求。R17因此挑战了一个简单假设：家里很热闹、常常聊天，就意味着每个人都能公开表达不同意见。"],["This distinction makes the silence of a child or younger relative more intelligible. If disagreement is interpreted as disrespect, a member may participate enthusiastically in daily conversation while concealing decisions about relationships, education or personal difficulties. But the family framework is not a direct count of all secrets, and it should not be used to assign a fixed label to a household without evidence of its everyday practices. Its contribution is conceptual: the amount of talk and the permission to disagree are different properties.","这一差别有助于理解儿童或年轻家人的沉默。如果不同意见会被理解为不尊重长辈，一个成员可能积极参加日常聊天，却隐瞒有关恋爱、学业或个人困境的决定。不过，家庭沟通框架并不是对所有家庭秘密进行的直接普查，也不能在不了解日常互动时就给某个家庭贴上固定标签。它的核心贡献是指出：说话的频率与表达异议的许可，属于两种不同的家庭特征。"],["R18 supplies a more specific test of what gets withheld from whom. Guerrero and Afifi found that adolescents and young adults tended to avoid discussing negative life experiences and dating more with parents than siblings, and more with male family targets; sexual matters were avoided more with opposite-sex relatives. Some relationship topics were least avoided in mother-daughter or sister relationships, while male respondents reported more avoidance on several categories. These findings do not mean every family follows the same pattern. They show that topic, gendered relationship and the particular listener jointly shape disclosure.","R18提供了更具体的证据，回答“什么话对谁更难说”。Guerrero与Afifi发现，青少年和年轻成年人相较于兄弟姐妹，更倾向于向父母回避负面生活经历与恋爱经历；面对男性家庭成员时，一些话题的回避也更多；性相关话题则更容易在异性家庭成员之间被回避。涉及关系和友谊的问题，在母女、姐妹等组合中通常更少被回避；男性受访者在若干话题上报告了更多回避。这不意味着每一个家庭都符合这些模式，而是说明话题内容、家庭成员关系和倾听对象的性别会共同影响披露。"],["R18 therefore specifies what R17 leaves open. A family may have an overall conversational climate, but its members do not speak equally to everyone about everything. Someone can confide in a sibling and remain silent before a parent; speak easily about study plans yet avoid discussing sexuality; disclose a difficulty to one caregiver and hide it from another. Silence is relationally selective, not always a property of the person as a whole. The study's demographic and historical setting also limits generalization across cultures and generations.","因此，R18填补了R17没有详细回答的部分：即使家庭具有某种整体沟通氛围，成员也不会向每一个人谈论每一种话题。一个人可能向兄弟姐妹倾诉，却在父母面前保持沉默；可以轻松讨论学业计划，却回避性话题；愿意向某位照护者讲述困难，却瞒着另一位。沉默往往具有关系选择性，而不必然是这个人整体“不爱说话”。该研究所处的时代与样本背景，也提醒我们不能未经检验就把模式推广到所有文化和世代。"],["R20 shifts from avoidance to the impulse to share. Rimé's theoretical and empirical review describes how emotionally significant events often stimulate people to recount their experiences to others. Social sharing can serve several functions: seeking connection, validation, assistance, meaning and social regulation. Yet the very fact that people retell an emotion does not show that they have resolved it. Recounting may sustain attention to a distressing event; listeners can respond differently; and sharing with someone outside the family need not be evidence that family ties are weak.","R20把视角从回避转向人们为何想分享。Rimé综合理论与经验研究指出，具有情绪冲击的事件往往会激发人们向他人反复讲述的需要。社会分享可能帮助人们寻求连接、确认、支持、意义以及社会性的情绪调节。但讲述过一件事，并不等于已经处理好与它相关的情绪；反复回忆也可能延长对痛苦事件的关注，不同听众的反应也会产生差异。一个人选择向家庭之外的人倾诉，更不能单凭这一点就认定家庭关系薄弱。"],["These findings create a productive contrast. R17 shows that family communication has an identifiable structure; R18 shows that lived disclosure follows the boundaries of particular relationships; R20 shows why people may seek an audience at all. A young person can strongly wish to share a painful experience yet decide that a parent is not the right listener. That is not inconsistent. The need to share and the judgement that a specific relationship is safe enough for sharing are separate questions.","这些发现形成了一种有解释力的对照。R17表明家庭沟通具有可以区分的结构，R18说明真实披露会沿着具体关系的边界变化，R20则帮助理解为什么人本身具有寻求倾听者的倾向。一个年轻人可能非常希望讲述痛苦经历，却判断父母不是合适的听众。这并不矛盾。“我需要说出来”和“我能够对这个人说出来”，本来就是两个不同的问题。"]]},
{head:["Explaining Agreements and Differences","共性、差异及其原因"],paras:[["The common thread is that disclosure depends on an audience, not only on the existence of a feeling. But the three works capture different parts of the process. R17 examines the climate that makes conversation or conformity normal; R18 identifies topic-specific boundaries around particular family members; R20 examines emotional sharing across relationships. A general family norm may shape expectations, but the immediate listener and the subject can still change a disclosure decision.","三项研究的共性在于：一个人是否讲述，不只取决于内心有没有感受，还取决于他面对怎样的听众。但三者捕捉了不同环节。R17考察让讨论或一致性要求成为常态的家庭氛围，R18识别不同家人和话题形成的具体边界，R20则讨论跨关系的情绪分享。家庭总体规范可能塑造预期，但眼前的倾听者是谁、要讲的是什么，仍然能够改变一次具体的表达选择。"],["An apparent contradiction—people tend to share strong feelings, yet avoid important topics at home—disappears once 'sharing' and 'sharing with parents' are separated. A distressed young adult may confide in a friend precisely because parental judgement seems likely. Alternatively, they may conceal a topic to avoid causing worry or to preserve autonomy. R18 establishes patterns of avoidance; it does not verify one motive behind every choice. R20 supplies possible functions of sharing, not an instruction that every feeling must be disclosed to family.","一个看似矛盾的现象是：人们往往想分享强烈情绪，却又把重要话题藏在家里。只要区分“想要分享”和“愿意告诉父母”，矛盾便不难理解。一个痛苦的年轻人可能因为预期会受到父母评判，反而选择向朋友倾诉；也可能为了避免父母担忧，或维护个人自主性而保留某些信息。R18说明存在不同的回避模式，却没有查明每次回避背后只有哪一种动机；R20解释分享可能具有的作用，却没有要求所有感受都必须向家人公开。"],["Family hierarchy may shape the meaning of disclosure. Parents often control resources, rules or evaluations in ways siblings do not, so telling a parent can entail consequences beyond being listened to. That is a plausible interpretation of R18's listener differences, not a direct causal result that all parental authority causes silence. Cultural expectations of obedience, generations' different norms and prior experiences of judgement could amplify or weaken these distinctions; those possibilities must be examined locally rather than assumed.","家庭中的权力关系也可能改变披露的意义。父母往往在规则、资源和评价方面拥有兄弟姐妹不具有的权力，所以告诉父母一件事，可能意味着承担比“有人听见”更多的后果。这是对R18听众差异的一种合理解释，却不是“所有父母的权威都会造成沉默”的直接因果结果。服从长辈的文化期待、代际观念差异和既往被评判的经验，都可能加强或削弱这些区别；这些可能性需要放在具体家庭中考察，不能想当然。"],["Finally, positive communication and unlimited disclosure should not be equated. A family may support conversation while respecting a member's privacy. Conversely, a household may demand that children report everything while providing little space for disagreement. The distinction between consent to speak and obligation to confess is essential. None of the three sources directly tests a universal ideal balance of family openness and privacy.","最后，还应区分积极沟通与无限披露。一个家庭可以鼓励讨论，同时尊重成员保留隐私；相反，一个家庭也可以要求孩子什么都汇报，却很少允许他们表达不同意见。自愿开口与被迫交代不是一回事。三项资料都没有直接验证一种适用于所有家庭的“开放与隐私最佳比例”。"]]},
{head:["The Museum’s Interpretation","本馆的综合结论"],paras:[["The Museum suggests that family silence often emerges from a mismatch between the desire to be understood and the conditions under which understanding seems possible. What remains unsaid may depend on the topic, the chosen listener, the household's tolerance for disagreement and the consequences anticipated after disclosure. A young person can be emotionally expressive with friends and reserved with parents without being inconsistent or dishonest.","本馆认为，家庭中的沉默往往可能产生于“希望被理解”与“相信能够被理解的条件”之间的落差。一个人究竟保留了什么，可能受到话题内容、倾听对象、家庭容纳分歧的程度，以及披露之后预期后果的共同影响。一个年轻人能与朋友坦诚交流，却对父母保持沉默，并不因此成为一个自相矛盾或不诚实的人。"],["Consequently, improving family dialogue cannot be reduced to asking children to 'say more'. The more important question may be what happens when they speak about something inconvenient: whether they can disagree without humiliation, refuse disclosure without punishment, and choose the timing and recipient of a difficult confidence. The presence of daily conversation is not enough to establish those protections.","因此，改善家庭沟通不能简化成要求孩子“多说一点”。更重要的是，当孩子说出不讨喜的内容时，接下来会发生什么：他能否在不被羞辱的情况下持有不同意见，能否在不受惩罚的情况下保留隐私，能否决定何时、向谁讲述一件困难的事。每天聊天很多，并不足以证明这些条件已经存在。"],["This is an interpretation based on three different literatures, not a causal model jointly tested by them. R17 provides a framework, R18 offers evidence about selective avoidance, and R20 discusses emotional sharing in broader social life. Together they justify a careful conclusion: silence within a family is not always a lack of feeling or trust; sometimes it is a judgement about the audience, the topic and the right to keep part of one's life one's own.","这是一项综合三类文献得出的本馆判断，而不是它们共同检验的因果模型。R17提供家庭沟通框架，R18提供选择性回避的经验资料，R20讨论更广泛社会生活中的情绪分享。三者让我们能够谨慎地得出结论：家庭中的沉默未必意味着没有感情或缺乏信任，有时它反映的是对听众、话题与个人隐私边界的具体判断。"]]},
{head:["References & Evidence Notes","参考文献与证据说明"],paras:[["R17 — Koerner & Fitzpatrick (2002), Understanding Family Communication Patterns and Family Functioning; R18 — Guerrero & Afifi (1995), Some Things Are Better Left Unsaid; R20 — Rimé (2009), Emotion Elicits the Social Sharing of Emotion. R17 develops and reviews a framework, R18 studies topic-specific family avoidance, and R20 reviews social emotional sharing beyond families; do not treat the three as equivalent family experiments.","R17 — Koerner与Fitzpatrick（2002），《Understanding Family Communication Patterns and Family Functioning》；R18 — Guerrero与Afifi（1995），《Some Things Are Better Left Unsaid》；R20 — Rimé（2009），《Emotion Elicits the Social Sharing of Emotion》。R17提出并讨论家庭沟通框架，R18调查家庭成员间的话题回避，R20综述超越家庭范围的情绪社会分享；不能把三者当作同样的家庭实验。"]]}
]
},
{
title:['The Imagined Audience','想象中的读者'],
subtitle:['What large-scale nonpublication data, interviews and privacy theories can—and cannot—tell us about holding words back.','大规模未发布行为数据、访谈与隐私理论，分别能告诉我们什么，又有哪些边界。'],
ids:['R22','R23','R24','R27'],
rows:[
['R22',['In a 17-day Facebook observation, 71% of analysed users had at least one measured nonpublication event; the study did not reveal draft contents or individual motives.','在17天的Facebook观察中，71%的可分析用户至少出现一次符合定义的未发布事件；研究没有揭示草稿内容或个人动机。'],['Establishes the scale of a platform-defined behaviour.','呈现平台操作定义下未发布行为的规模。']],
['R23',['Twitter users described managing imagined audiences through context cues, indirect language and self-presentation strategies.','Twitter用户描述了如何通过情境线索、间接表达和自我呈现策略管理想象中的受众。'],['Explains how people think about who may read their words.','解释人们如何想象可能阅读自己文字的人。']],
['R24',['Teenagers negotiate networked privacy through social relationships and audience management; technical settings cannot guarantee privacy.','青少年通过社会关系和受众管理协商网络隐私；技术设置无法完全保证隐私。'],['Shows privacy as relational negotiation rather than a simple public/private switch.','把隐私呈现为关系协商，而非简单的公开／私密开关。']],
['R27',['Privacy-boundary theory treats disclosure as negotiated ownership and coordination of private information.','隐私边界理论将披露理解为私人信息所有权与边界协调的过程。'],['Offers a framework for interpreting disclosure choices, not direct evidence about a particular draft.','提供理解披露选择的理论框架，而非某份草稿动机的直接证据。']]
],
sections:[
{head:["Research Background & Literature","研究背景与文献介绍"],paras:[["A message can be composed without ever becoming public. R22 measures abandoned Facebook posts and comments at scale; R23 explores how Twitter users imagine the people who might read them; R24 examines teenagers' negotiation of privacy across interconnected audiences; and R27 provides a theory of boundaries around private information. Together they move from the observable act of nonpublication toward possible social conditions for withholding, without pretending that a platform log can reveal the writer's inner motives.","一条消息可以被写出来，却始终没有公开。R22在大规模Facebook数据中测量输入后未发布的帖子和评论；R23研究Twitter使用者如何想象可能阅读自己内容的人；R24考察青少年如何在相互连接的受众之间协商隐私；R27则提出管理私人信息边界的理论。它们让我们从可以观察的“未发布”行为，逐步走向理解沉默可能发生的社会条件，却不应假装平台日志能够直接揭示写作者内心的真实动机。"]]},
{head:["Comparative Analysis of Research Findings","研究结论的深度比较"],paras:[["R22 establishes scale. Across a seventeen-day observation window and 3,941,161 analyzable Facebook accounts, 71% entered at least one post or comment that was not submitted within the study's ten-minute rule. The study also reported that roughly 33% of potential posts and 13% of potential comments met its operational definition of self-censorship. The denominators differ: 71% refers to users, whereas 33% and 13% refer to attempted content of different kinds. None is a measure of how many people 'secretly wanted to confess' something intimate.","R22首先证明这种行为具有相当大的规模。在17天的观察期内，3,941,161个可分析的Facebook账户中，71%至少有一次输入帖子或评论，却没有在研究规定的10分钟内提交。研究还报告，约33%的潜在帖子与13%的潜在评论符合其“自我审查”的操作性定义。这里必须区分分母：71%以用户为单位，33%与13%则分别以不同类别的潜在内容为单位。任何一个数字都不能被解释为“有多少人暗中想向别人倾诉隐私”。"],["The research also did not preserve the abandoned words as interpretable private messages. Researchers could identify that composition activity did not lead to submission within the rule, but not whether an abandoned draft was affectionate, angry, ordinary, mistaken or interrupted. Some entries may have been reconsidered for audience reasons; others may have been rewritten, delayed or abandoned for practical reasons. R22 is unusually strong evidence that nonpublication is common, but weak evidence about why any individual pressed no button.","研究也没有把被放弃的文字保存为可供分析的私人内容。研究者能够识别某次输入活动没有在规定时间内形成提交，却无法因此知道草稿是表达爱意、愤怒、日常闲聊，还是一次误输入。有人可能因为顾虑受众而删除，也有人可能只是改写、延迟或被其他事情打断。因此，R22对“未发布行为相当常见”提供了强有力的数量证据，却不能充分解释某个具体用户为什么最终没有按下发布键。"],["R23 approaches the missing question qualitatively. Using 226 responses from 181 Twitter users, Marwick and boyd explored the imagined audience: the readers to whom a person orients a statement even when the actual audience is uncertain. Social media can collapse colleagues, friends, acquaintances and strangers into one visible feed. A post directed at close friends may also reach someone for whom its humour or criticism has a different meaning. This research illustrates why composing for a platform is not simply speaking to a known listener.","R23通过质性资料靠近R22无法回答的问题。Marwick与boyd分析181位Twitter用户提供的226份回应，讨论“想象中的受众”：当实际读者并不确定时，用户仍会在心中设想自己在向谁说话。社交媒体可能使同事、朋友、熟人和陌生人出现在同一个信息流中。一条原本写给好友的玩笑或批评，也可能被完全不同的读者看到，并得到另一种解释。研究由此说明，在平台上写字并不等同于对一个确定的听众说话。"],["R23 does not calculate how many drafts are suppressed for a given audience. What it reveals is a dilemma of self-presentation. A speaker can adjust tone, edit details or avoid a topic to keep a coherent impression before several groups at once. The question becomes less 'Am I brave enough to publish?' than 'Which version of myself, and which implied relationship, will this publication announce?' That interpretive difference matters because self-presentation is not automatically dishonesty; it is often an ordinary response to mixed contexts.","R23并未计算究竟有多少草稿因为顾虑受众而被放弃。它揭示的更重要问题是自我呈现的两难：一个人可能调整语气、删去细节或避开某个话题，以便在不同群体面前维持某种能够被理解的形象。问题因此未必只是“我敢不敢发布”，还包括“这次发布会向别人呈现怎样的我，以及怎样的关系”。这种解释很重要，因为自我呈现并不自动等于虚伪，它常常是人们面对不同社交语境时的普通策略。"],["R24 develops the privacy problem through teenagers' practices. Marwick and boyd argue that privacy in networked environments is not just an individual choice between public and private settings. A teenager might limit direct visibility yet remain exposed through friends' posts, screenshots, tags or shared contexts. People therefore negotiate privacy through relationships and social expectations, not only through a platform menu. The findings complement R23's imagined audience by explaining why even a carefully selected audience may not remain bounded.","R24进一步通过青少年的网络实践讨论隐私。Marwick与boyd指出，在相互连接的网络环境中，隐私并不是个人在“公开”和“私密”设置之间做一次选择那么简单。青少年即使限制了个人页面的直接可见性，仍可能因为朋友的帖子、截图、标记或共享情境而被其他人看见。因此，隐私需要在关系和社会期待中不断协商，而不仅靠平台菜单完成。R24补充了R23关于想象受众的分析：即使一个人认真选择了读者，读者边界也不一定能够保持稳定。"],["R27 offers a theoretical explanation of that instability. Petronio's Communication Privacy Management approach treats private information as governed by boundaries, disclosure rules and expectations about shared control. Once a secret is told to another person, the receiver may become a co-holder who can handle it in ways the original speaker did not intend; disagreement about these rules can create boundary turbulence. Unlike R22, this is not a dataset of abandoned posts. It helps articulate why 'being heard' and 'controlling onward circulation' are different goals.","R27用理论框架进一步解释这种不稳定。Petronio的传播隐私管理理论认为，私人信息受到边界、披露规则和共同控制期待的约束。一旦秘密告诉了别人，听者就可能成为信息的共同持有者，并可能以原本说话者未曾预期的方式处理它；双方对规则的理解不一致，就可能产生隐私边界冲突。与R22不同，R27不是关于未发布帖子的行为数据，而是帮助我们说明：“让一个人听见”与“控制信息之后如何传播”，是两个不同的目标。"]]},
{head:["Explaining Agreements and Differences","共性、差异及其原因"],paras:[["These works agree that public communication is shaped by an audience that may not be fully knowable or controllable. But they measure different things. R22 measures the gap between composing and submitting; R23 explores how people imagine possible readers; R24 shows how social ties make privacy collective; R27 theorizes the rules governing ownership and disclosure. They cannot be arranged as if one statistical finding had demonstrated each step of a single causal chain.","四项资料的共性是：公开表达受到那些难以完全知道、也难以完全控制的受众影响。但它们测量的并不是同一个对象。R22统计输入与提交之间的落差，R23分析用户如何想象读者，R24说明社交关系为何使隐私具有集体性，R27则解释信息拥有与披露的规则。不能把它们排列起来，就声称一项统计研究已经证明了整条“害怕被看见—犹豫—删除”的因果链。"],["A further difference is between visibility and circulation. A person may accept that a close friend can read a post while fearing that a wider group could later see it. An audience can be imagined at the moment of writing, but the eventual audience can change after publication. R23 identifies the difficulty of addressing multiple audiences at once; R24 and R27 direct attention to the fragility of control after sharing. R22 cannot tell us how often either concern caused a specific abandoned draft.","还需要区分“谁能看到”与“内容之后如何流转”。一个人可能愿意让好友阅读，却担心内容随后传播到更广泛的人群。写作时可以在脑中设想读者，但内容发布后的读者却会不断变化。R23揭示同时面对多类受众的困难，R24和R27则将注意力转向内容被分享之后控制权的脆弱性。R22无法告诉我们，究竟有多少篇草稿是因为其中哪一种顾虑而被放弃。"],["The studies also emerge from different platform generations and populations. A Twitter user surveyed in an earlier social-media environment is not the same as a teenager negotiating contemporary networked privacy; a Facebook composing event is a behavioural record, not a statement of felt anxiety. These differences make cross-study interpretation possible but limit direct generalization to every platform, age group or algorithmic environment.","研究还处于不同的平台时代与使用人群之中。早期社交媒体环境中接受调查的Twitter用户，不能直接等同于在网络化环境中协商隐私的青少年；Facebook上的一次输入事件是行为记录，而不是一份关于焦虑程度的自述。这些差异不妨碍我们进行概念比较，却限制了将结论直接推广到每个年龄群体、平台和算法环境。"],["A final tension concerns the moral framing of nonpublication. Editing a post may represent fear of judgement; it may also represent care for another person's privacy, the desire to prevent misunderstanding or an entirely ordinary revision. The term 'self-censorship' is an operational label in R22, not a moral diagnosis. None of the four sources allows a museum to turn every unposted sentence into a silenced confession.","最后还有一个关于价值判断的张力。删除或修改帖子可能源于害怕被评判，也可能出于对他人隐私的尊重、避免误解，或者只是普通的文字修改。R22中的“自我审查”是一种操作性研究标签，并非道德诊断。四项资料都不允许本馆把每一段没有发布的文字，自动叙述为遭到压抑的真心告白。"]]},
{head:["The Museum’s Interpretation","本馆的综合结论"],paras:[["The Museum suggests that the threshold between typing and publishing is a social boundary, not merely a technical button. A writer may be considering several distinct questions: who will read this, how will different readers interpret it, who may pass it on, and what cannot be taken back once it travels? A message may be linguistically complete while remaining socially unfinished because its audience is unresolved.","本馆认为，从输入到发布之间的门槛，不只是一个技术按钮，也是一条社会边界。写作者可能同时考虑多个不同问题：谁会读到？不同读者会怎样理解？谁可能继续转发？内容传播之后又有什么无法收回？因此，一条消息在语言上已经写完，却可能因为听众与传播边界尚未确定，而在社会意义上仍未完成。"],["This conclusion does not imply that every abandoned draft is evidence of oppression. Sometimes holding back protects privacy, preserves nuance or respects another person's confidence. At other times it may reflect a genuine inability to speak safely. A responsible account of unsent digital words must distinguish the observable event of nonpublication from an unobserved intention, and should not invent the text of a missing post.","这一结论不意味着每一个放弃的草稿都证明有人受到压迫。保留不发，有时是在维护隐私、保留复杂性或尊重他人的秘密；另一些时候，它也可能确实反映了无法安全发声。负责任地解释未发布的数字文字，必须把可观察的“没有发布”与不可直接观察的“为什么没发布”区分开，更不能虚构那些从未被研究者取得的文字内容。"],["The four sources do not jointly prove one causal model. What they do justify is the Museum's more limited claim: in networked communication, the decision to publish depends not only on what a person wishes to say but also on the audiences, relationships and privacy boundaries that publication may set in motion. Silence may therefore be an exercise of agency as well as a sign of constraint.","四项资料并未共同证明一个完整的因果模型。它们支持本馆提出更有限的判断：在网络化沟通中，是否发布不仅取决于一个人想说什么，还取决于发布会调动怎样的受众、关系与隐私边界。因此，沉默有时是受限的表现，也可能是对自身信息主动行使控制权的一种方式。"]]},
{head:["References & Evidence Notes","参考文献与证据说明"],paras:[["R22 — Das & Kramer (2013), Self-Censorship on Facebook; R23 — Marwick & boyd (2011), I Tweet Honestly, I Tweet Passionately; R24 — Marwick & boyd (2014), Networked Privacy; R27 — Petronio (2002), Boundaries of Privacy. R22's ten-minute operational definition cannot identify the content or motive of an abandoned draft. R23/R24 are qualitative investigations; R27 is a theoretical framework.","R22 — Das与Kramer（2013），《Self-Censorship on Facebook》；R23 — Marwick与boyd（2011），《I Tweet Honestly, I Tweet Passionately》；R24 — Marwick与boyd（2014），《Networked Privacy》；R27 — Petronio（2002），《Boundaries of Privacy》。R22以10分钟为操作性界限，无法识别草稿内容或放弃动机；R23与R24是质性研究，R27则是理论框架。"]]}
]
},
{
title:['Writing for Oneself','为自己而写作'],
subtitle:['A comparison of platform nonpublication, expressive-writing experiments and emotion-regulation theory.','比较平台未发布行为、表达性写作实验与情绪调节理论。'],
ids:['R22','R26','R28'],
rows:[
['R22',['Many users had at least one platform-defined nonpublication event, but the study could not identify the content or motive.','许多用户至少出现一次平台定义下的未发布事件，但研究无法识别内容或动机。'],['Shows that composing and publishing can be separate actions.','呈现写下与公开发布可以是不同的行动。']],
['R26',['Writing about both facts and feelings could increase immediate distress while relating to fewer health-centre visits over the following six months.','同时书写经历事实与情绪可能增加即时不适，却与随后六个月较少的校内医疗中心就诊次数有关。'],['Shows different short-term and later outcomes in a specific writing task.','呈现特定写作任务中短期与后续结果的差异。']],
['R28',['The review explains emotion regulation as a broader process with different strategies and stages; it offers no single effect for private writing.','综述将情绪调节解释为包含不同策略与阶段的广泛过程，并未给私人写作提供一个统一效应量。'],['Offers a framework, not direct proof that every private text is therapeutic.','提供理论框架，而非每段私人文字都有疗愈作用的直接证明。']]
],
sections:[
{head:["Research Background & Literature","研究背景与文献介绍"],paras:[["Not every written sentence is meant to be sent. A private page may serve a different purpose from a public post, and the decision to keep it private need not mean writing has failed. R26 tests a short expressive-writing practice; R28 provides a framework for emotion regulation; R22 documents digital writing that did not become public. These works can be compared by separating the act of putting feelings into words from the distinct choice to share those words with an audience.","并不是每一句写下来的话都准备寄出。私人书写可能有不同于公开发布的目的，而保留文字也不意味着写作失败。R26实验性地研究短期表达性写作，R28提供情绪调节的过程框架，R22则记录社交平台上没有变成公开内容的文字输入。比较这三项资料，首先要分清两件事：把感受组织成文字，与决定是否让他人看见这些文字，并不是同一个行为。"]]},
{head:["Comparative Analysis of Research Findings","研究结论的深度比较"],paras:[["R26 provides the most direct evidence about writing itself. Pennebaker and Beall assigned 46 undergraduate students to brief writing conditions across four consecutive days, each lasting fifteen minutes. Some wrote about personally traumatic experiences, with conditions distinguishing the facts and emotions of those experiences; controls wrote about more ordinary material. Writing about both facts and feelings was associated with greater immediate negative mood and physiological arousal following the sessions, but fewer visits to a campus health centre during the subsequent six months.","R26提供了最直接关于写作本身的实验性证据。Pennebaker与Beall将46名大学本科生分配至不同的书写条件，在连续四天里每天写作15分钟。部分参与者书写个人创伤经历，研究还区分了关于事实与情绪的内容；对照条件则涉及较普通的题材。把事件事实与情绪一并写下的人，写完后可能出现更强的即时负面情绪和生理唤醒；但在随后六个月中，研究观察到他们前往校内健康中心的次数相对较少。"],["The coexistence of short-term discomfort and a later health-related association is the first finding that resists a comforting cliché. Expressive writing is not necessarily pleasant while it is happening. It may bring painful material into attention instead of instantly releasing it. Nor can a reduction in recorded campus visits, in a small and specific student sample, be treated as proof that writing cures trauma, prevents disease or produces identical benefits across age groups. The study supports a limited possibility, not a universal prescription.","即时不舒服与后续健康相关指标同时出现，是这项研究最值得认真对待、也最不符合安慰性套话的发现。表达性写作在进行时未必令人愉快，它可能让痛苦经历重新进入注意力，而不是瞬间把情绪“排出去”。同时，在特定的小规模学生样本中观察到校内就诊次数减少，不能被当作写作能够治愈创伤、防止疾病，或适用于所有年龄群体的证明。研究支持的是一种有限的可能性，而不是一剂普遍有效的处方。"],["R28 is different in both purpose and evidence. Gross's 1998 integrative review proposes that emotion regulation can occur at several moments: choosing or modifying situations, directing attention, changing an interpretation, and modulating responses once emotions arise. This is a framework for understanding how emotions unfold and can be managed, not an experiment in which participants wrote unsent letters. It helps us ask what a writing practice might change—attention, appraisal or response—without claiming that R26 has isolated a particular regulation pathway.","R28在研究目的与证据类型上都不同。Gross于1998年提出的整合性综述认为，情绪调节可以发生在多个环节：选择或改变情境、调整注意力、改变对事件的解释，以及在情绪已经出现后调节反应。这是一套理解情绪如何产生与被调节的过程框架，并不是让参与者写未寄出信件的实验。它帮助我们追问写作可能改变了什么——注意力、事件解释还是情绪反应——却不能因此声称R26已经隔离出某一种确定的调节机制。"],["One way to link the two cautiously is to distinguish expression from reappraisal. Writing 'I was hurt' can make an experience legible without changing its meaning. Writing a coherent account that connects feelings, circumstances and an altered perspective might involve a further interpretive process. R26's combined fact-and-emotion condition makes that possibility worth considering, while R28 offers conceptual vocabulary for it. But neither source establishes that all benefits of writing are due to cognitive reappraisal rather than other processes or circumstances.","把R26与R28谨慎联系起来的一种方式，是区分情绪表达与重新解释事件。写下“我受伤了”，可能只是让经验变得可以辨认，并未改变它的意义；如果写作者进一步把感受、事件背景与新的理解联系起来，则可能涉及更深的解释过程。R26对事实与情绪共同书写的安排使这一可能性值得考虑，R28也为它提供了概念语言。但两者都没有证明，写作的所有可能益处都来自认知重评，而非其他心理过程或情境因素。"],["R22 then complicates any easy equation of writing and publishing. In a seventeen-day study of 3,941,161 analyzable Facebook users, 71% entered at least one item that was not submitted under the ten-minute definition; 33% of potential posts and 13% of potential comments were not submitted according to their respective denominators. Yet the researchers did not observe the content of those abandoned messages, and the record cannot tell whether users experienced relief, distress, regret or nothing remarkable at all. R22 measures a publishing outcome, not a writing-health outcome.","R22使“写出来”与“发布出去”的关系更加复杂。在为期17天、涉及3,941,161名可分析Facebook用户的研究中，71%的人至少有一次输入的内容未在规定的10分钟内提交；潜在帖子和评论中分别约有33%与13%未发布，但它们使用的是不同分母。然而，研究者没有分析这些草稿的具体内容，也无法知道用户是感到轻松、痛苦、后悔，还是根本没有特别感受。R22测量的是发布行为的结果，而不是写作对健康或情绪的影响。"],["The comparison therefore rejects two symmetrical assumptions. It is not true that writing matters only when someone reads it: R26 studies writing undertaken without publishing to an audience. But it is equally unwarranted to claim that every unpublished message was therapeutic: R22 provides no such outcome. Between these extremes lies a more interesting possibility, that writing and sharing can serve different purposes within the same life and may be chosen independently.","这组比较因此同时否定了两种对立但同样简单的假设。不能认为只有别人读到，写作才有意义：R26研究的书写并不以公开发布为目的。但也不能把每一条未发布的信息都说成一种自我疗愈：R22根本没有测量这样的结果。两种极端之间存在更值得讨论的可能性：写作与分享在同一个人的生活中可能服务于不同目的，而且可以分别作出选择。"]]},
{head:["Explaining Agreements and Differences","共性、差异及其原因"],paras:[["The largest difference is in what the studies observe. R26 experimentally changes a writing task and follows psychological and health-related measures; R22 records whether digital composition becomes a submission; R28 summarizes the architecture of emotional regulation. The first can speak cautiously about effects of an assigned exercise in a small sample, the second about prevalence of nonpublication in one platform setting, and the third about possible regulatory processes. Combining them into one finding would be a category error.","三项资料最大的差异是它们究竟观察了什么。R26通过实验安排不同写作任务，并追踪心理和健康相关指标；R22记录平台输入活动是否变成提交；R28总结情绪调节过程的理论结构。第一项可以谨慎讨论特定小样本中某项书写练习的影响，第二项可以描述特定平台中未发布现象的普遍程度，第三项则用于解释可能的情绪机制。把三者拼成同一个“研究发现”，是证据类型上的错误。"],["Time scale explains part of the seeming contradiction between distress and benefit. R26 measures an immediate experience after writing and also looks months later. A practice can feel painful now and still be linked to a different later outcome, just as an immediately soothing activity need not produce long-term change. This does not tell us which individual should undertake trauma writing. It tells us that comfort during a session is not equivalent to the full range of possible outcomes.","时间尺度解释了痛苦与潜在益处之间的一部分表面矛盾。R26既测量写完后的即时体验，也观察数月之后的指标。一项练习可能当下令人痛苦，却与之后的某个结果存在关联；反过来，一件事立即让人舒服，也不保证长期变化。但这并不告诉我们具体哪个人适合进行创伤书写。它说明，写作当下是否舒适，与可能出现的全部后续结果不是同一个问题。"],["Purpose and audience are another difference. The research participants in R26 were asked to undertake a structured exercise; Facebook users in R22 may have been composing for particular audiences for countless everyday reasons. A private journal is not simply a failed social-media post, and an unsent letter to someone who caused harm is not identical to a laboratory writing task. Their emotional meanings may differ even when all involve written sentences that no public reader encounters.","目的和受众是另一种差异。R26的参与者接受的是有结构的书写任务；R22中的用户可能为了无数日常理由面向特定读者写字。私人日记不是一次失败的社交媒体发帖；写给伤害过自己、却没有寄出的信，也不等同于实验室里的写作任务。即使三者都产生了没有公开读者的文字，其情感意义也可能完全不同。"],["Finally, not communicating something should not automatically be described as emotional suppression. A person may choose not to disclose a feeling while still recognising and working through it privately. Equally, an unpublished draft may reflect avoidance rather than processing; without content or outcome measures, the distinction remains unknown. Gross's framework helps identify different possible emotion processes, but it does not classify an individual's silent act from appearance alone.","最后，不向别人表达某件事，不应自动被定义为情绪压抑。一个人可能决定不透露感受，却仍在私人空间中承认并理解它；相反，一份未发布草稿也可能体现回避，而不是情绪处理。如果没有文字内容和后续结果，我们就无法区分这些情况。Gross的框架有助于辨认不同的情绪过程，却不能仅凭沉默的外表诊断一个人的内心。"]]},
{head:["The Museum’s Interpretation","本馆的综合结论"],paras:[["The Museum suggests that writing can be a form of action even when no message reaches another person. It may give a difficult event a sequence, provide words for a previously inarticulate feeling, or make possible a new interpretation. But these are potential functions that depend on the person and circumstances, not automatic benefits attached to every page. Writing privately deserves recognition without being romanticized as a cure.","本馆认为，即使没有任何文字送到别人手中，写作仍可能是一种行动。它可能为混乱经历整理顺序，为此前无法说明的情绪找到语言，或者使新的理解成为可能。但这些只是依赖个人和情境的潜在作用，而非每写下一页就自动获得的好处。私人书写值得被看见，却不应被浪漫化成治愈一切的办法。"],["The decision not to send a text is also a separate action with its own ethics. One may write a complaint to clarify what happened and then decide that contacting the recipient is unsafe. One may compose a letter to someone who cannot answer, or draft something too personal to share. Such choices do not erase the significance of writing. Nor do they prove that the act of withholding is beneficial. The distinction between composing and delivering gives a person room to decide what belongs to the self and what is entrusted to others.","不寄出文字本身也是另一项具有独立伦理意义的选择。有人写下控诉，是为了弄清事件经过，最终却判断与对方联系并不安全；有人写信给永远无法回应的人；也有人写下太私密、暂时不愿分享的内容。这些选择不会抹去写作的意义，也不意味着保留文字就必然有益。把书写与送达区分开，才允许一个人判断哪些内容属于自己，哪些内容愿意交给他人。"],["The cited works do not test unsent letters as a single therapy, nor demonstrate that withholding heals. The museum's narrower conclusion is that the value of writing should not be judged by publication alone. An unshared text can still matter to its author, while its meaning and consequences remain open questions requiring evidence rather than projection.","所引研究没有把未寄信件作为统一疗法加以检验，也没有证明保留不发能够疗愈。本馆能够提出的更有限结论是：不能只凭是否发表来评价写作的价值。一份无人阅读的文字仍可能对作者重要，但它具体意味着什么、带来了什么结果，仍需证据而不是旁观者的想象。"]]},
{head:["References & Evidence Notes","参考文献与证据说明"],paras:[["R22 — Das & Kramer (2013), Self-Censorship on Facebook; R26 — Pennebaker & Beall (1986), Confronting a Traumatic Event; R28 — Gross (1998), The Emerging Field of Emotion Regulation. R22 records nonpublication, R26 reports a small expressive-writing experiment, and R28 reviews theory; none directly tests whether writing an unsent personal letter produces healing.","R22 — Das与Kramer（2013），《Self-Censorship on Facebook》；R26 — Pennebaker与Beall（1986），《Confronting a Traumatic Event》；R28 — Gross（1998），《The Emerging Field of Emotion Regulation》。R22记录未发布行为，R26报告小样本表达性写作实验，R28综述理论；三者都没有直接验证“写一封未寄出的私人信件就能够疗愈”。"]]}
]
},
{
title:['Whose Voice Survives?','谁的声音能够留存？'],
subtitle:['A historical and methodological comparison of archives, domination, oral testimony, representation and research refusal.','比较档案、支配关系、口述证词、代表性与研究拒访，理解历史声音如何留存。'],
ids:['R29','R30','R31','R32','R33','R34','R35','R36'],
rows:[
['R29',['Historical facts are shaped by power at the moments of source creation, archiving, narrative and later significance.','权力会在史料形成、档案保存、历史叙述和后世赋予意义等环节影响历史事实。'],['Explains how silence can enter the production of history.','解释沉默如何进入历史生产过程。']],
['R30',['Public and hidden transcripts distinguish official performance from less visible criticism under domination.','公开话语与隐藏话语区分了支配关系下的官方表演与不易被看见的批评。'],['Shows why public speech may not represent private belief.','说明公开表达为何未必代表私人信念。']],
['R31',['Violent archives can make a person’s life impossible to reconstruct fully; imaginative narration has ethical limits.','暴力档案可能使一个人的生命无法被完整重建；想象性叙述具有伦理边界。'],['Confronts the impossibility of recovering a lost individual voice.','直面失落的个人声音无法被完整复原的问题。']],
['R32',['Colonial archives reveal officials’ anxieties and classificatory habits, not neutral records alone.','殖民档案呈现官员的焦虑与分类习惯，而非中立记录。'],['Treats archival language itself as evidence.','把档案语言本身作为证据。']],
['R33',['Representation determines who can be recognized as a speaking subject; it is not simply a question of physical voice.','代表性结构决定谁能被承认为发声主体；问题不只是有没有声音。'],['Raises the ethics of speaking for others.','提出代替他人发声的伦理问题。']],
['R34',['Differences between oral memory and chronology can reveal meaning, while still requiring factual verification.','口述记忆与事件时间线的差异可能揭示意义，但仍需事实核查。'],['Shows oral testimony as interpretation as well as evidence.','呈现口述证词既是史料，也是解释行动。']],
['R35',['Researchers’ interview settings and methods can produce refusal or silence; changing the setting may enable conversation.','研究者的采访场景和方法可能造成拒访或沉默；改变场景有时能促成交流。'],['Makes the researcher’s role part of the evidence.','把研究者自身角色纳入证据分析。']],
['R36',['Silence can be chosen, imposed or protective; speech may occur without being heard or recognized.','沉默可能是主动选择、强迫排除或自我保护；说话也不代表一定被聆听或承认。'],['Offers a broad anthropological synthesis while noting cultural limits.','提供人类学综合视角，同时指出文化情境的限制。']]
],
sections:[
{head:["Research Background & Literature","研究背景与文献介绍"],paras:[["Whose words become history, and what can a museum responsibly do when a voice was never recorded? This comparison draws on eight works that do not share one method. R29 examines the production of historical silence; R32 reads colonial archives as practices of rule; R31 and R33 question representation; R30 distinguishes public and hidden accounts under domination; R34 interprets oral memory; and R35–R36 explore the methodological and relational meanings of silence. Their convergence cannot be measured by one effect size. It must be argued across different kinds of evidence.","谁的话最终能够成为历史？面对那些从未被记录的声音，博物馆又能负责任地做什么？本专题比较的八项资料并不采用同一种方法。R29研究历史沉默如何产生，R32把殖民档案看作统治实践，R31与R33质疑替他人发声的代表性，R30区分支配关系中的公开与隐藏话语，R34研究口述记忆，R35与R36则从研究方法和人类学关系的角度讨论沉默。它们的共性无法被一个效应量概括，而必须在不同证据类型之间建立严谨的解释。"]]},
{head:["Comparative Analysis of Research Findings","研究结论的深度比较"],paras:[["R29 gives the comparison its structural starting point. Trouillot argues that silence enters historical production at four moments: when sources are created, when archives are assembled, when facts are retrieved for narratives, and when later generations assign historical significance. This matters because recovering a neglected document does not undo every earlier exclusion. A person might have lacked access to record-making in the first place; their surviving words might later have been selected or interpreted by institutions that did not value their experience.","R29为比较提供了结构性的起点。Trouillot指出，沉默可能在历史生产的四个环节进入：史料被创造时、档案被汇集时、事实被提取用来写叙事时，以及后世赋予某段历史重要性时。这意味着，即使今天找回一份被忽略的文件，也不等于消除了此前所有排除。某个人可能从一开始就没有制作记录的条件；即便文字保存下来，也可能在后续筛选和解释中，被不重视其经历的机构再次忽视。"],["R32 makes this argument more material. Studying colonial archives, Stoler asks not only what officials wrote, but how their categories, conventions, worries and administrative habits shaped what became recordable. A colonial file is not a neutral window onto the governed population: it also documents the preoccupations of those governing. R32 strengthens R29 by showing mechanisms inside archival practices rather than treating 'bias' as an occasional mistake that a conscientious historian could simply subtract.","R32把这种结构问题进一步落实到具体档案实践。Stoler研究殖民档案时，不只关注官员写了什么，也考察他们使用怎样的分类、记录习惯、制度惯例与焦虑，进而决定什么值得记录。殖民文件并不是透视被统治者生活的一扇中性窗户，它同时记录了统治者自身的关注与预设。R32由此具体化了R29：档案偏向不是历史学家偶尔犯下、之后只需小心删除的误差，它可能从文件生产的制度过程开始就已形成。"],["R31 pushes the problem further by attending to people who appear in an archive mainly through the violence done to them. In Venus in Two Acts, Hartman considers the fragmentary records surrounding enslaved women and girls and the risk that reconstruction can reproduce the very power that made their lives almost illegible. Inventing a vivid first-person interior life may create an emotionally satisfying narrative, but it can also replace an unknown person's experience with the historian's desire. R31 therefore challenges the fantasy that every archival gap can be repaired by imaginative prose.","R31把问题推进到那些只因为遭受暴力，才偶然在档案里留下痕迹的人。Hartman在《Venus in Two Acts》中面对被奴役女性与女孩的残缺记录，思考重构她们生活时，写作者是否可能再次复制导致这些生命难以被认识的权力关系。虚构一段生动的第一人称心理独白，或许在情感上让故事显得完整，却也可能以研究者自己的愿望取代当事人无人能知的经验。R31因此质疑一种看似善意的幻想：只要文学想象足够丰富，所有档案空白都能被填补。"],["R33's challenge to representation is related, but not identical. Spivak's question about whether the subaltern can speak is not simply a claim that marginalised people have no language or never act. It concerns how institutional, intellectual and political arrangements shape whether their utterances can appear as an intelligible voice, and how others claim to represent them. R31 makes the ethical cost vivid in historical narration; R33 warns that even a well-meaning spokesperson may reproduce unequal relations by declaring that they have finally delivered another person's authentic voice.","R33关于代表性的质疑与R31相近，却不完全相同。Spivak提出“底层者能否发声”，并不是简单宣称边缘群体不会说话、没有语言或从不行动；她更关心制度、知识与政治结构如何决定他们的话能否作为一种可被理解的声音出现，以及别人如何声称自己能够代表他们。R31让这种风险在历史叙述中变得具体，R33则提醒我们：即使出于善意，代言者一旦宣称自己终于完整传达了他人的“真实声音”，也可能重新制造不平等的关系。"],["R30 complicates the apparent absence of voice from another angle. Scott distinguishes performances of assent before power from criticisms circulated out of its direct view. A quiet official record may therefore coexist with vigorous speech, complaint or resistance elsewhere. This does not mean every silence secretly hides opposition. The point is more precise: official visibility and actual expression are different distributions. What enters the ruler's archive may not exhaust what subordinated people said or thought among themselves.","R30从另一侧使“缺乏声音”的判断变得复杂。Scott区分人们在权威面前表现出的附和，与权力视线之外流传的批评。官方记录里的安静，完全可能与其他空间中活跃的抱怨、议论和抵抗同时存在。这并不意味着每一次沉默都暗藏反抗。更准确的意义是：被官方看见的表达与实际存在的表达，并不具有相同的分布。进入统治者档案的文字，不一定穷尽从属群体彼此之间说过、想过的事情。"],["R34 offers a different kind of surviving evidence: oral testimony. Portelli's study of memories surrounding Luigi Trastulli's death shows that discrepancies between recollection and a documented chronology can illuminate how a community later made meaning of loss. When narrators move an event in time or attach it to another struggle, the discrepancy is not historically accurate evidence about the date itself; it may nonetheless be evidence about collective memory. R34 adds a methodological requirement: distinguish what a testimony verifies about an event from what it reveals about the narrator's later understanding.","R34提供另一种留下来的证据：口述证词。Portelli对Luigi Trastulli之死的记忆研究发现，口述回忆与可以核实的事件时间线之间存在差异，而这种差异又能帮助我们理解一个社群后来如何赋予失去与抗争以意义。叙述者把事件放到另一年、另一场冲突中，并不构成关于实际日期的准确证据，却可能构成关于集体记忆的重要证据。R34因此提出一个方法上的要求：必须区分证词能核实事件中的什么，与它能说明叙述者后来怎样理解事件。"],["R35 shifts from historical material to the process of obtaining testimony. Schweiger and Tomiak describe a research episode in which 25 initial interview invitations to disadvantaged participants led to only four interviews. That is a local methodological episode, not the population's overall refusal rate. Their analysis asks how scholarly expectations—formal invitations, recording equipment, interview spaces, assumptions about who should explain themselves—can make participation difficult. A change of place or relationship can alter what becomes sayable. The researcher's own methods are therefore part of the conditions producing the apparent absence of data.","R35把目光从历史文献转向证词是如何被取得的。Schweiger与Tomiak讨论的一段研究经历中，面向处境不利群体发出的25次初始访谈邀请，最终只促成四次访谈。这个数字说明的是一次具体研究的招募困难，而不是整个群体的普遍拒访率。作者进一步追问：正式邀请、录音设备、访谈空间、要求受访者解释自身经历的学术期待，是否本身就在增加参与难度？换一个地点、改变相处关系，可能就会改变人们愿意说什么。研究者使用的方法，因此也可能成为资料缺席的形成条件。"],["R36 broadens the meaning of silence rather than assigning it one moral value. Dragojlovic and Samuels review anthropological work in which silence can be relational, embodied, affective, culturally situated and sometimes active. A pause may express care, respect, refusal, grief or something not accessible to an outside observer. The review does not license a curator to choose whichever hidden meaning sounds most poetic. Instead it warns that silence is not always a vacuum waiting for words, and that interpretation requires knowledge of the social setting.","R36则进一步拓宽“沉默”的意义，而不是为它赋予一种固定的道德价值。Dragojlovic与Samuels综述人类学研究，指出沉默可能具有关系性、身体性、情感性与文化情境，也可能是一种主动实践。一次停顿有时关联照顾、尊重、拒绝或哀悼，有时它的意义根本无法被外部观察者确定。这并不是允许策展人挑一个最富诗意的解释加进去，而是在提醒我们：沉默不一定只是等待语言填补的真空，解释它必须了解具体社会情境。"]]},
{head:["Explaining Agreements and Differences","共性、差异及其原因"],paras:[["The strongest common finding is not that all missing voices were forcibly suppressed. It is that surviving evidence is shaped by conditions of production, circulation and interpretation. Trouillot and Stoler locate these conditions in archives; Scott locates them in relations of domination and different audiences; Schweiger and Tomiak show them emerging in the contemporary research encounter. These perspectives support one another while preserving a crucial distinction between a voice never uttered, a voice uttered privately, a voice not recorded and a voice recorded but later neglected.","八项资料最重要的共性，并不是“所有消失的声音都遭到了强制压制”，而是：能够留下的证据受到生产、传播与解释条件的塑造。Trouillot与Stoler在档案制度中寻找这些条件，Scott在支配关系与不同听众之间寻找它们，Schweiger与Tomiak则指出它们也会出现在当代研究者与受访者的接触中。这些视角相互支持，同时要求我们严格区分：话从未说出、说出却只留在私人空间、说了却没有被记录，以及被记录却在后来遭到忽视。"],["There is a genuine methodological tension between reconstruction and restraint. Portelli demonstrates that testimony with factual errors can still preserve meaning; Hartman insists that profound absence cannot simply be filled through imaginative certainty. These are not contradictory positions if we distinguish the object of interpretation. An oral account is evidence that someone actually told a story, which can be investigated and attributed. A first-person monologue invented for someone whose words were never preserved is not such evidence. Empathetic reconstruction becomes misleading when it hides that difference.","重构与克制之间存在真正的方法论张力。Portelli说明，即使证词在事实上存在错误，也可能保存重要的社群意义；Hartman则坚持，深刻的证据缺席不能通过富有想象力的确信轻易填补。如果区分解释对象，这两种立场并不矛盾。一份口述史至少证明某个人确实讲述过那个故事，研究者可以追问并标明出处；而为一位话语从未保存下来的人虚构第一人称独白，却不具有同样的证据地位。当同情性的重构掩盖了这一差别，它就会误导读者。"],["R33 adds another difficulty: the institution that promises to restore a voice may become the institution defining what that voice should mean. A museum might select only testimony that confirms a simple story of victimhood and overlook survival strategies, ambivalence or refusal to participate. R30 and R36 counter this risk by showing that not all meaningful expression takes the form of public disclosure, and not all quiet signifies helplessness. Representation becomes more responsible when it allows uncertainty and contradictory accounts to remain visible.","R33又指出另一个困难：宣称要恢复某种声音的机构，可能反而成为决定这种声音应该意味着什么的机构。博物馆可能只挑选符合“受害者故事”的证词，而忽略当事人的生存策略、矛盾感受，甚至拒绝参与的意愿。R30与R36提醒我们，并非所有有意义的表达都以公开披露出现，也并非所有安静都等同于无力。让不确定性与相互矛盾的叙述保持可见，往往比强行提供完整一致的故事更负责任。"],["Different scales of evidence also explain why the sources cannot simply be averaged. R29–R33 are primarily historical, critical and theoretical arguments; R34 interprets an oral-history case; R35 discusses methodological episodes; R36 provides a selective anthropological synthesis. No study gives the percentage of all historical people whose voices are missing. R35's four interviews out of 25 requests cannot serve as a general statistic for archival silencing, any more than a theoretical argument can be represented as a laboratory effect size.","证据尺度不同，也说明为什么不能把八项资料简单求平均。R29至R33主要提出历史、批判和理论分析；R34解释一项口述史案例；R35讨论研究过程中的方法问题；R36提供具有选择性的人类学综述。没有哪项研究能够计算历史上所有人究竟有百分之多少失去了声音。R35的25次邀请与四次访谈，更不能当作整个人类档案沉默的统计数据，正如理论论证不能被包装成实验效应量一样。"],["A final distinction concerns who has the right not to speak. Archival exclusion by powerful institutions is not the same as a living person's decision to decline an interview. The first can signal the denial of historical participation; the second may express privacy, caution or justified distrust of the researcher. Treating every refusal to be recorded as a problem the museum must overcome risks repeating the appropriation it claims to oppose.","最后还必须区分“没有机会发声”与“有权选择不发声”。强势机构将某些人排除在档案生产之外，不等于一位仍然在世的人决定拒绝受访。前者可能意味着历史参与机会被剥夺；后者可能体现隐私、谨慎，或对研究者有充分理由的不信任。如果把所有拒绝被记录的行为都视为博物馆必须克服的障碍，就可能重演本馆原本声称要反对的攫取。"]]},
{head:["The Museum’s Interpretation","本馆的综合结论"],paras:[["The Museum concludes that historical silence has several forms that must never be collapsed: experiences prevented from entering a record, statements kept outside official hearing, evidence lost or devalued after being recorded, and deliberate choices not to testify. Each form requires a different curatorial response. The first calls for investigation of the structures that excluded people; the second for attention to unofficial channels; the third for transparent methods of source criticism; the fourth for respect for consent and privacy.","本馆认为，历史沉默至少包含几种不能混为一谈的形式：某些经历从一开始就没有进入记录的机会；某些话只在官方听不到的场合传播；某些证据被记录之后又遗失或遭到贬低；还有一些人主动选择不提供证词。每一种情况都需要不同的策展回应。第一种要求追查排除机制，第二种需要关注非官方表达渠道，第三种要求公开透明的史料批判，第四种则必须尊重同意权与隐私。"],["Our task is therefore not to make every empty space sound full. Where evidence survives, we should identify whose record it is, when it was created, who mediated it and what it can substantiate. Where oral accounts disagree with documented chronology, we should distinguish event facts from remembered significance. Where nothing reliable survives, we should make the absence visible and describe its causes where evidence permits, rather than composing an invented confession in the dead person's voice.","因此，本馆的任务不是把每一处空白都填满声音。有证据保存下来时，应当说明记录由谁制作、发生在何时、经过谁的转述，以及它究竟能够证明什么。口述史与可核实时间线不一致时，应当区分事件事实和被记忆赋予的意义。没有可靠证据时，则应诚实地呈现空白，并在有依据的情况下解释其形成原因，而不是替已经无法回答的人编造一段感人告白。"],["Such restraint does not mean accepting the official archive as complete. On the contrary, the comparison shows that a well-preserved file can be evidence of power as much as evidence of ordinary life. The museum should read documents against their conditions of production, search for multiple forms of testimony, and remain alert to the people whom a record was never designed to hear. It must also recognise that a person's decision to remain private is not automatically an injustice to be corrected.","这种克制并不意味着接受官方档案已经完整。恰恰相反，比较表明，一份保存完好的文件可能同样是权力运作的证据，而不仅是日常生活的记录。本馆应当把文件放回其生产条件中阅读，寻找不同类型的证词，并注意那些原本就不被档案制度视为倾听对象的人。同时，本馆也必须承认，一个人决定保留私人生活，并不自动构成需要被纠正的不公。"],["This is a methodological and ethical interpretation assembled across unlike sources, not a tested formula for recovering lost voices. Its guiding principle is narrower but demanding: represent what the evidence can support, mark what remains unknown, and never confuse the museum's wish to speak for someone with that person's own surviving speech. A history that acknowledges the limits of hearing may be more faithful than one that claims to have heard everyone.","这是本馆跨越不同证据类型形成的方法与伦理判断，而不是一条已经验证的“找回失落声音公式”。它遵循的原则更有限，却也更严格：只陈述证据能够支持的内容，明确标记尚不可知的部分，永远不要把博物馆希望替某人说的话，混同于当事人真正留下来的声音。承认自身倾听能力有限的历史叙述，可能比声称听见所有人的叙述更加忠实。"]]},
{head:["References & Evidence Notes","参考文献与证据说明"],paras:[["R29 — Trouillot (1995), Silencing the Past; R30 — Scott (1990), Domination and the Arts of Resistance; R31 — Hartman (2008), Venus in Two Acts; R32 — Stoler (2009), Along the Archival Grain; R33 — Spivak (1988), Can the Subaltern Speak?; R34 — Portelli (1991), The Death of Luigi Trastulli and Other Stories; R35 — Schweiger & Tomiak (2022), Researching Silence; R36 — Dragojlovic & Samuels (2023), Silence. These comprise theory, historical criticism, oral history, methodological discussion and anthropology—not eight comparable experiments. R35's 25 invitations and four interviews refer to one research episode only.","R29 — Trouillot（1995），《Silencing the Past》；R30 — Scott（1990），《Domination and the Arts of Resistance》；R31 — Hartman（2008），《Venus in Two Acts》；R32 — Stoler（2009），《Along the Archival Grain》；R33 — Spivak（1988），《Can the Subaltern Speak?》；R34 — Portelli（1991），《The Death of Luigi Trastulli and Other Stories》；R35 — Schweiger与Tomiak（2022），《Researching Silence》；R36 — Dragojlovic与Samuels（2023），《Silence》。资料涵盖理论、历史批判、口述史、研究方法与人类学，而非八项可直接横向统计的实验；R35的25次邀请与四次访谈只属于一次具体研究经历。"]]}
]
}
];

/* Expanded cross-study analysis: added after the source-by-source audit.
   Each pair is English / Simplified Chinese; Traditional Chinese is rendered
   through the museum's existing language converter. */
/* Eight articles are rewritten in place; obsolete appended comparison passages removed. */
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lang=()=>{const current=window.museumLangPublic?.();return current==='en'?'en':current==='zh-Hant'?'zh-Hant':'zh-Hans';};
const cv=s=>lang()==='zh-Hant'?(window.museumConvertPublic?.(String(s??''))??String(s??'')):String(s??'');
const t=p=>esc(lang()==='en'?p[0]:cv(p[1]));
const nav=()=>'<nav class="atlas-nav" aria-label="'+esc(lang()==='en'?'Research navigation':cv('研究导航'))+'"><a href="#/research">'+esc(lang()==='en'?'Research library':cv('研究资料馆'))+'</a><a href="#/research/audit">'+esc(lang()==='en'?'Source verification':cv('来源核实'))+'</a><a href="#/research/method">'+esc(lang()==='en'?'Curatorial method':cv('策展方法'))+'</a></nav>';
function render(i){
 const a=articles[i];if(!a)return '';
 const title=t(a.title),subtitle=t(a.subtitle);
 const hero='<section class="page-hero"><div class="eyebrow">'+esc(lang()==='en'?'THE UNSENT MUSEUM · COMPARATIVE RESEARCH':cv('未寄之言博物馆 · 跨研究比较'))+'</div><h1>'+title+'</h1><p class="muted">'+subtitle+'</p><p class="atlas-essay-count">'+esc(String(i+1).padStart(2,'0')+' / 08')+' · '+a.ids.length+' '+esc(lang()==='en'?'research sources':cv('项研究来源'))+'</p></section>';
 const table='<div class="atlas-evidence-table"><table><thead><tr><th>'+esc(lang()==='en'?'Study':cv('研究'))+'</th><th>'+esc(lang()==='en'?'Main finding':cv('原始结论重点'))+'</th><th>'+esc(lang()==='en'?'Contribution to comparison':cv('对比较的贡献'))+'</th></tr></thead><tbody>'+a.rows.map(r=>'<tr><td><a href="#/research/study/'+esc(r[0])+'">'+esc(r[0])+'</a></td><td>'+t(r[1])+'</td><td>'+t(r[2])+'</td></tr>').join('')+'</tbody></table></div>';
 const sections=a.sections.map((s,j)=>{
  const body=s.paras.map(p=>'<p>'+t(p)+'</p>').join('');
  return '<section class="atlas-panel atlas-comparison-section atlas-comparison-section-'+(j+1)+'"><span class="eyebrow">'+String(j+1).padStart(2,'0')+' · '+t(s.head)+'</span><h2>'+t(s.head)+'</h2>'+(j===1?table:'')+body+'</section>';
 }).join('');
 const refs='<section class="atlas-panel atlas-comparison-sources"><span class="eyebrow">SOURCE DOSSIERS</span><h2>'+esc(lang()==='en'?'Research dossiers and source notes':cv('研究档案与来源说明'))+'</h2><div class="atlas-study-list">'+a.ids.map(id=>'<a class="atlas-study-link" href="#/research/study/'+id+'"><span>'+id+'</span><strong>'+esc(lang()==='en'?'Open research dossier':cv('打开研究档案'))+'</strong><small>'+esc(lang()==='en'?'Source details and verification status':cv('查看原始来源与核查状态'))+'</small></a>').join('')+'</div></section>';
 const prev=i>0?'<a class="btn btn-outline" href="#/research/compare/'+(i-1)+'">← '+esc(lang()==='en'?'Previous comparison':cv('上一篇比较'))+'</a>':'';
 const next=i<7?'<a class="btn btn-outline" href="#/research/compare/'+(i+1)+'">'+esc(lang()==='en'?'Next comparison':cv('下一篇比较'))+' →</a>':'';
 return '<main class="container atlas-page" lang="'+(lang()==='en'?'en':lang()==='zh-Hant'?'zh-Hant':'zh-Hans')+'">'+nav()+hero+sections+refs+'<div class="atlas-comparison-pagination">'+prev+next+'<a class="btn btn-outline" href="#/research">'+esc(lang()==='en'?'Back to research library':cv('返回研究资料馆'))+'</a></div></main>';
}
const original=atlas.page;
atlas.page=function(id){
 if(typeof id==='string'&&id.startsWith('compare/')){
  const n=Number(id.split('/')[1]);
  if(Number.isInteger(n)&&n>=0&&n<articles.length)return render(n);
 }
 const html=original.call(this,id);
 if(typeof id!=='string'||typeof html!=='string')return html;
 if(!id.startsWith('study/')||!html.includes('atlas-deep'))return html;
 return html.replace(/<section class="atlas-panel">(?=<span class="eyebrow">(?:SOURCE AUDIT|来源核对))/,'<section class="atlas-panel atlas-verification-plate">').replace(/<section class="atlas-panel">(?=<h2>(?:Research Connections|研究关联)<\/h2>)/,'<section class="atlas-panel atlas-connections-gallery">');
};
})();
